// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import "@openzeppelin/contracts/utils/cryptography/EIP712.sol";

/**
 * @title MinimalForwarder
 * @dev Simple minimal forwarder to be used together with an ERC2771 compatible contract.
 * This is a basic implementation suitable for TrataTech gasless transactions.
 */
contract MinimalForwarder is EIP712 {
    using ECDSA for bytes32;

    struct ForwardRequest {
        address from;
        address to;
        uint256 value;
        uint256 gas;
        uint256 nonce;
        bytes data;
    }

    bytes32 private constant _TYPEHASH =
        keccak256("ForwardRequest(address from,address to,uint256 value,uint256 gas,uint256 nonce,bytes data)");

    mapping(address => uint256) private _nonces;

    event MetaTransactionExecuted(address indexed from, address indexed to, bytes indexed data);

    constructor() EIP712("MinimalForwarder", "0.0.1") {}

    function getNonce(address from) public view returns (uint256) {
        return _nonces[from];
    }

    function verify(ForwardRequest calldata req, bytes calldata signature) public view returns (bool) {
        address signer = _hashTypedDataV4(
            keccak256(abi.encode(_TYPEHASH, req.from, req.to, req.value, req.gas, req.nonce, keccak256(req.data)))
        ).recover(signature);
        return _nonces[req.from] == req.nonce && signer == req.from;
    }

    function execute(ForwardRequest calldata req, bytes calldata signature)
        public
        payable
        returns (bool, bytes memory)
    {
        require(verify(req, signature), "MinimalForwarder: signature does not match request");
        _nonces[req.from] = req.nonce + 1;

        (bool success, bytes memory returndata) = req.to.call{gas: req.gas, value: req.value}(
            abi.encodePacked(req.data, req.from)
        );

        // Validate that the relayer has sent enough gas for the call.
        // See https://ronan.eth.limo/blog/ethereum-gas-dangers/
        if (gasleft() <= req.gas / 63) {
            // We explicitly trigger invalid opcode to consume all gas and bubble-up the effects, since
            // neither revert or assert consume all gas since Solidity 0.8.0
            // https://docs.soliditylang.org/en/v0.8.0/control-flow.html#panic-via-assert-and-error-via-require
            /// @solidity memory-safe-assembly
            assembly {
                invalid()
            }
        }

        emit MetaTransactionExecuted(req.from, req.to, req.data);
        return (success, returndata);
    }
}

contracts/forwarder/TrataTechForwarder.s.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import "@openzeppelin/contracts/utils/cryptography/EIP712.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title TrataTechForwarder
 * @dev Enhanced forwarder contract for TrataTech ecosystem with additional features:
 * - Access control and whitelisting
 * - Gas limits and rate limiting
 * - Emergency controls
 * - Analytics and monitoring
 * 
 * This forwarder is fully compatible with ERC-2771 standard and maintains
 * all existing functionality while adding enterprise-grade features.
 */
contract TrataTechForwarder is EIP712, Ownable, Pausable, ReentrancyGuard {
    using ECDSA for bytes32;

    struct ForwardRequest {
        address from;
        address to;
        uint256 value;
        uint256 gas;
        uint256 nonce;
        bytes data;
        uint256 deadline;
    }

    bytes32 private constant _TYPEHASH =
        keccak256("ForwardRequest(address from,address to,uint256 value,uint256 gas,uint256 nonce,bytes data,uint256 deadline)");

    // Core storage
    mapping(address => uint256) private _nonces;

    // Enhanced features
    mapping(address => bool) public whitelistedTargets;
    mapping(address => bool) public whitelistedRelayers;
    mapping(address => uint256) public lastRequestTime;
    mapping(address => uint256) public requestCount;

    // Configuration
    uint256 public maxGasLimit = 5000000; // 5M gas limit
    uint256 public minGasLimit = 21000;   // Minimum gas for transfer
    uint256 public rateLimitPeriod = 3600; // 1 hour
    uint256 public maxRequestsPerPeriod = 100;
    bool public requireTargetWhitelist = false;
    bool public requireRelayerWhitelist = false;

    // Statistics
    uint256 public totalTransactions = 0;
    mapping(address => uint256) public userTransactionCount;
    mapping(address => uint256) public targetTransactionCount;

    // Events
    event MetaTransactionExecuted(
        address indexed from, 
        address indexed to, 
        bytes indexed data,
        bool success,
        uint256 gasUsed
    );

    event TargetWhitelisted(address indexed target, bool whitelisted);
    event RelayerWhitelisted(address indexed relayer, bool whitelisted);
    event ConfigurationUpdated(string parameter, uint256 value);
    event RateLimitExceeded(address indexed user, uint256 requestCount, uint256 timeWindow);

    constructor() EIP712("TrataTechForwarder", "1.0.0") Ownable(msg.sender) {}

    // ============ CORE FORWARDER FUNCTIONS ============

    function getNonce(address from) public view returns (uint256) {
        return _nonces[from];
    }

    function verify(ForwardRequest calldata req, bytes calldata signature) public view returns (bool) {
        // Verify deadline
        if (req.deadline != 0 && block.timestamp > req.deadline) {
            return false;
        }

        // Verify gas limits
        if (req.gas > maxGasLimit || req.gas < minGasLimit) {
            return false;
        }

        // Verify signature
        address signer = _hashTypedDataV4(
            keccak256(abi.encode(_TYPEHASH, req.from, req.to, req.value, req.gas, req.nonce, keccak256(req.data), req.deadline))
        ).recover(signature);

        return _nonces[req.from] == req.nonce && signer == req.from;
    }

    function execute(ForwardRequest calldata req, bytes calldata signature)
        public
        payable
        whenNotPaused
        nonReentrant
        returns (bool, bytes memory)
    {
        // Verify the request
        require(verify(req, signature), "TrataTechForwarder: Invalid signature or request");

        // Check target whitelist if enabled
        if (requireTargetWhitelist) {
            require(whitelistedTargets[req.to], "TrataTechForwarder: Target not whitelisted");
        }

        // Check relayer whitelist if enabled
        if (requireRelayerWhitelist) {
            require(whitelistedRelayers[msg.sender], "TrataTechForwarder: Relayer not whitelisted");
        }

        // Rate limiting check
        _checkRateLimit(req.from);

        // Update nonce
        _nonces[req.from] = req.nonce + 1;

        // Update statistics
        _updateStatistics(req.from, req.to);

        // Execute the call
        uint256 gasBeforeExecution = gasleft();
        (bool success, bytes memory returndata) = req.to.call{gas: req.gas, value: req.value}(
            abi.encodePacked(req.data, req.from)
        );
        uint256 gasUsed = gasBeforeExecution - gasleft();

        // Gas validation (same as MinimalForwarder)
        if (gasleft() <= req.gas / 63) {
            assembly {
                invalid()
            }
        }

        emit MetaTransactionExecuted(req.from, req.to, req.data, success, gasUsed);
        return (success, returndata);
    }

    // ============ BATCH EXECUTION ============

    function executeBatch(
        ForwardRequest[] calldata requests,
        bytes[] calldata signatures
    ) external payable whenNotPaused nonReentrant returns (bool[] memory, bytes[] memory) {
        require(requests.length == signatures.length, "TrataTechForwarder: Length mismatch");
        require(requests.length <= 10, "TrataTechForwarder: Batch too large");

        bool[] memory successes = new bool[](requests.length);
        bytes[] memory results = new bytes[](requests.length);

        for (uint256 i = 0; i < requests.length; i++) {
            (successes[i], results[i]) = execute(requests[i], signatures[i]);
        }

        return (successes, results);
    }

    // ============ ADMIN FUNCTIONS ============

    function setTargetWhitelist(address target, bool whitelisted) external onlyOwner {
        whitelistedTargets[target] = whitelisted;
        emit TargetWhitelisted(target, whitelisted);
    }

    function setRelayerWhitelist(address relayer, bool whitelisted) external onlyOwner {
        whitelistedRelayers[relayer] = whitelisted;
        emit RelayerWhitelisted(relayer, whitelisted);
    }

    function setRequireTargetWhitelist(bool required) external onlyOwner {
        requireTargetWhitelist = required;
        emit ConfigurationUpdated("requireTargetWhitelist", required ? 1 : 0);
    }

    function setRequireRelayerWhitelist(bool required) external onlyOwner {
        requireRelayerWhitelist = required;
        emit ConfigurationUpdated("requireRelayerWhitelist", required ? 1 : 0);
    }

    function setGasLimits(uint256 min, uint256 max) external onlyOwner {
        require(min < max && min >= 21000, "TrataTechForwarder: Invalid gas limits");
        minGasLimit = min;
        maxGasLimit = max;
        emit ConfigurationUpdated("gasLimits", max);
    }

    function setRateLimits(uint256 period, uint256 maxRequests) external onlyOwner {
        rateLimitPeriod = period;
        maxRequestsPerPeriod = maxRequests;
        emit ConfigurationUpdated("rateLimits", maxRequests);
    }

    function pause() external onlyOwner {
        _pause();
    }

    function unpause() external onlyOwner {
        _unpause();
    }

    // ============ INTERNAL FUNCTIONS ============

    function _checkRateLimit(address user) internal {
        uint256 currentTime = block.timestamp;

        // Reset counter if enough time has passed
        if (currentTime > lastRequestTime[user] + rateLimitPeriod) {
            requestCount[user] = 0;
            lastRequestTime[user] = currentTime;
        }

        // Check rate limit
        if (requestCount[user] >= maxRequestsPerPeriod) {
            emit RateLimitExceeded(user, requestCount[user], rateLimitPeriod);
            require(false, "TrataTechForwarder: Rate limit exceeded");
        }

        requestCount[user]++;
    }

    function _updateStatistics(address from, address to) internal {
        totalTransactions++;
        userTransactionCount[from]++;
        targetTransactionCount[to]++;
    }

    // ============ VIEW FUNCTIONS ============

    function getUserStats(address user) external view returns (
        uint256 nonce,
        uint256 transactionCount,
        uint256 currentRequestCount,
        uint256 lastRequest
    ) {
        return (
            _nonces[user],
            userTransactionCount[user],
            requestCount[user],
            lastRequestTime[user]
        );
    }

    function getContractStats() external view returns (
        uint256 totalTxs,
        uint256 maxGas,
        uint256 minGas,
        bool targetWhitelistEnabled,
        bool relayerWhitelistEnabled
    ) {
        return (
            totalTransactions,
            maxGasLimit,
            minGasLimit,
            requireTargetWhitelist,
            requireRelayerWhitelist
        );
    }

    // ============ EMERGENCY FUNCTIONS ============

    function emergencyWithdraw(address payable to) external onlyOwner {
        require(to != address(0), "TrataTechForwarder: Invalid address");
        to.transfer(address(this).balance);
    }

    // Allow contract to receive ETH for gas sponsorship
    receive() external payable {}
}

contracts/TrataTechMain.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import "@openzeppelin/contracts/utils/cryptography/MerkleProof.sol";
import "@openzeppelin/contracts/utils/Strings.sol";


/**
 * @title TrataTechMain
 * @dev Comprehensive smart contract for TrataTech platform handling:
 * - Event Invites & RSVP
 * - Product Launches & Early Access
 * - Digital Product Passports
 * - Digital Art Drops
 * - Offers & Coupons
 * @author Advanced Developer
 */
contract TrataTechMain is ERC721, Ownable, Pausable, ReentrancyGuard {

    using ECDSA for bytes32;
    using Strings for uint256;


    // ============ STRUCTS ============

    struct EventInvite {
        uint256 eventId;
        string eventName;
        string eventDescription;
        uint256 eventDate;
        uint256 maxAttendees;
        uint256 currentAttendees;
        string ipfsCID;
        bool isActive;
        bool isCancelled;
        mapping(address => bool) attendees;
        mapping(address => uint256) attendeeTokens;
    }

    struct ProductLaunch {
        uint256 launchId;
        string productName;
        string productDescription;
        uint256 launchDate;
        uint256 earlyAccessEndDate;
        string ipfsCID;
        bool isActive;
        bool isLaunched;
        uint256 maxEarlyAccess;
        uint256 currentEarlyAccess;
        mapping(address => bool) earlyAccessUsers;
        mapping(address => uint256) preOrders;
    }

    struct DigitalProductPassport {
        uint256 dppId;
        string productId;
        string brandId;
        string ipfsCID;
        uint256 timestamp;
        bool isValid;
        address creator;
        string metadataHash;
    }

    struct DigitalArtDrop {
        uint256 dropId;
        string artistName;
        string artworkTitle;
        uint256 edition;
        uint256 maxEditions;
        string ipfsCID;
        bool isActive;
        bool isLimited;
        mapping(address => bool) airdroppedTo;
    }

    struct Offer {
        uint256 offerId;
        string title;
        uint256 discountPercentage;
        uint256 validFrom;
        uint256 validUntil;
        string productScope;
        string conditions;
        string ipfsCID;
        bool isActive;
        bool isMerkleBased;
        bytes32 merkleRoot;
        uint256 maxRedemptions;
        uint256 currentRedemptions;
        mapping(address => bool) redeemedBy;
        mapping(address => uint256) userRedemptions;
    }

    // ============ STATE VARIABLES ============

    uint256 private _tokenIds = 0;
    uint256 private _eventIds = 0;
    uint256 private _launchIds = 0;
    uint256 private _dppIds = 0;
    uint256 private _dropIds = 0;
    uint256 private _offerIds = 0;

    // Mappings
    mapping(uint256 => EventInvite) private _events;
    mapping(uint256 => ProductLaunch) private _launches;
    mapping(uint256 => DigitalProductPassport) private _dpps;
    mapping(uint256 => DigitalArtDrop) private _drops;
    mapping(uint256 => Offer) private _offers;

    // Token type mapping
    mapping(uint256 => TokenType) private _tokenTypes;
    mapping(uint256 => uint256) private _tokenReferences; // Maps tokenId to specific ID (eventId, launchId, etc.)

    // Access control
    mapping(address => bool) private _authorizedBrands;
    mapping(address => bool) private _authorizedOperators;

    // Fee structure
    uint256 private _platformFee = 250; // 2.5% in basis points
    uint256 public constant FEE_DENOMINATOR = 10000;

    // Emergency controls
    bool private _emergencyStop = false;

    // ============ ENUMS ============

    enum TokenType {
        EVENT_INVITE,
        PRODUCT_LAUNCH,
        DIGITAL_ART,
        OFFER_COUPON,
        DPP_PASSPORT
    }

    // ============ EVENTS ============

    event EventCreated(uint256 indexed eventId, string eventName, uint256 eventDate, string ipfsCID);
    event EventCancelled(uint256 indexed eventId);
    event RSVPSubmitted(uint256 indexed eventId, address indexed attendee, uint256 tokenId);
    event RSVPCancelled(uint256 indexed eventId, address indexed attendee);

    event ProductLaunchCreated(uint256 indexed launchId, string productName, uint256 launchDate, string ipfsCID);
    event EarlyAccessGranted(uint256 indexed launchId, address indexed user, uint256 tokenId);
    event PreOrderPlaced(uint256 indexed launchId, address indexed user, uint256 amount);

    event DPPCreated(uint256 indexed dppId, string productId, string brandId, string ipfsCID);
    event DPPInvalidated(uint256 indexed dppId);

    event ArtDropCreated(uint256 indexed dropId, string artistName, string artworkTitle, string ipfsCID);
    event ArtAirdropped(uint256 indexed dropId, address indexed recipient, uint256 tokenId);

    event OfferCreated(uint256 indexed offerId, string title, uint256 discountPercentage, string ipfsCID);
    event OfferRedeemed(uint256 indexed offerId, address indexed user);
    event OfferExpired(uint256 indexed offerId);

    event BrandAuthorized(address indexed brand);
    event BrandRevoked(address indexed brand);
    event OperatorAuthorized(address indexed operator);
    event OperatorRevoked(address indexed operator);
    event EmergencyStopActivated();
    event EmergencyStopDeactivated();

    // ============ MODIFIERS ============

    modifier onlyAuthorizedBrand() {
        require(_authorizedBrands[msg.sender] || msg.sender == owner(), "Not authorized brand");
        _;
    }

    modifier onlyAuthorizedOperator() {
        require(_authorizedOperators[msg.sender] || msg.sender == owner(), "Not authorized operator");
        _;
    }

    modifier notEmergencyStopped() {
        require(!_emergencyStop, "Contract is emergency stopped");
        _;
    }

    modifier validEvent(uint256 eventId) {
        require(_events[eventId].eventId != 0, "Event does not exist");
        require(_events[eventId].isActive, "Event is not active");
        require(!_events[eventId].isCancelled, "Event is cancelled");
        _;
    }

    modifier validLaunch(uint256 launchId) {
        require(_launches[launchId].launchId != 0, "Launch does not exist");
        require(_launches[launchId].isActive, "Launch is not active");
        _;
    }

    modifier validOffer(uint256 offerId) {
        require(_offers[offerId].offerId != 0, "Offer does not exist");
        require(_offers[offerId].isActive, "Offer is not active");
        require(block.timestamp >= _offers[offerId].validFrom, "Offer not yet valid");
        require(block.timestamp <= _offers[offerId].validUntil, "Offer expired");
        _;
    }

    // ============ CONSTRUCTOR ============

    constructor() ERC721("TrataTech Platform", "TRATA") Ownable(msg.sender) {
        _tokenIds = 1; // Start from 1
    }

    // ============ GETTER FUNCTIONS ============

    function events(uint256 eventId) external view returns (
        uint256 eventId_,
        string memory eventName,
        string memory eventDescription,
        uint256 eventDate,
        uint256 maxAttendees,
        uint256 currentAttendees,
        string memory ipfsCID,
        bool isActive,
        bool isCancelled
    ) {
        EventInvite storage eventData = _events[eventId];
        return (
            eventData.eventId,
            eventData.eventName,
            eventData.eventDescription,
            eventData.eventDate,
            eventData.maxAttendees,
            eventData.currentAttendees,
            eventData.ipfsCID,
            eventData.isActive,
            eventData.isCancelled
        );
    }

    function launches(uint256 launchId) external view returns (
        uint256 launchId_,
        string memory productName,
        string memory productDescription,
        uint256 launchDate,
        uint256 earlyAccessEndDate,
        string memory ipfsCID,
        bool isActive,
        bool isLaunched,
        uint256 maxEarlyAccess,
        uint256 currentEarlyAccess
    ) {
        ProductLaunch storage launch = _launches[launchId];
        return (
            launch.launchId,
            launch.productName,
            launch.productDescription,
            launch.launchDate,
            launch.earlyAccessEndDate,
            launch.ipfsCID,
            launch.isActive,
            launch.isLaunched,
            launch.maxEarlyAccess,
            launch.currentEarlyAccess
        );
    }

    function offers(uint256 offerId) external view returns (
        uint256 offerId_,
        string memory title,
        uint256 discountPercentage,
        uint256 validFrom,
        uint256 validUntil,
        string memory productScope,
        string memory conditions,
        string memory ipfsCID,
        bool isActive,
        bool isMerkleBased,
        bytes32 merkleRoot,
        uint256 maxRedemptions,
        uint256 currentRedemptions
    ) {
        Offer storage offer = _offers[offerId];
        return (
            offer.offerId,
            offer.title,
            offer.discountPercentage,
            offer.validFrom,
            offer.validUntil,
            offer.productScope,
            offer.conditions,
            offer.ipfsCID,
            offer.isActive,
            offer.isMerkleBased,
            offer.merkleRoot,
            offer.maxRedemptions,
            offer.currentRedemptions
        );
    }

    function tokenTypes(uint256 tokenId) external view returns (TokenType) {
        return _tokenTypes[tokenId];
    }

    function tokenReferences(uint256 tokenId) external view returns (uint256) {
        return _tokenReferences[tokenId];
    }

    function authorizedBrands(address brand) external view returns (bool) {
        return _authorizedBrands[brand];
    }

    function authorizedOperators(address operator) external view returns (bool) {
        return _authorizedOperators[operator];
    }

    function platformFee() external view returns (uint256) {
        return _platformFee;
    }

    function emergencyStop() external view returns (bool) {
        return _emergencyStop;
    }

    // ============ EVENT MANAGEMENT ============

    /**
     * @dev Create a new event invite
     * @param eventName Name of the event
     * @param eventDescription Description of the event
     * @param eventDate Unix timestamp of the event
     * @param maxAttendees Maximum number of attendees
     * @param ipfsCID IPFS CID containing event metadata
     */
    function createEventInvite(
        string memory eventName,
        string memory eventDescription,
        uint256 eventDate,
        uint256 maxAttendees,
        string memory ipfsCID
    ) external onlyAuthorizedBrand notEmergencyStopped returns (uint256) {
        require(bytes(eventName).length > 0, "Event name cannot be empty");
        require(eventDate > block.timestamp, "Event date must be in the future");
        require(maxAttendees > 0, "Max attendees must be greater than 0");
        require(bytes(ipfsCID).length > 0, "IPFS CID cannot be empty");

        _eventIds = _eventIds + 1;
        uint256 eventId = _eventIds;

        EventInvite storage newEvent = _events[eventId];
        newEvent.eventId = eventId;
        newEvent.eventName = eventName;
        newEvent.eventDescription = eventDescription;
        newEvent.eventDate = eventDate;
        newEvent.maxAttendees = maxAttendees;
        newEvent.currentAttendees = 0;
        newEvent.ipfsCID = ipfsCID;
        newEvent.isActive = true;
        newEvent.isCancelled = false;

        emit EventCreated(eventId, eventName, eventDate, ipfsCID);
        return eventId;
    }

    /**
     * @dev Submit RSVP for an event
     * @param eventId ID of the event
     */
    function submitRSVP(uint256 eventId) external validEvent(eventId) notEmergencyStopped nonReentrant {
        EventInvite storage eventData = _events[eventId];

        require(!eventData.attendees[msg.sender], "Already RSVP'd");
        require(eventData.currentAttendees < eventData.maxAttendees, "Event is full");
        require(block.timestamp < eventData.eventDate, "Event has already started");

        // Mint NFT ticket
        _tokenIds = _tokenIds + 1;
        uint256 tokenId = _tokenIds;

        _safeMint(msg.sender, tokenId);

        // Update event data
        eventData.attendees[msg.sender] = true;
        eventData.attendeeTokens[msg.sender] = tokenId;
        eventData.currentAttendees = eventData.currentAttendees + 1;

        // Set token type and reference
        _tokenTypes[tokenId] = TokenType.EVENT_INVITE;
        _tokenReferences[tokenId] = eventId;

        emit RSVPSubmitted(eventId, msg.sender, tokenId);
    }

    /**
     * @dev Cancel RSVP for an event
     * @param eventId ID of the event
     */
    function cancelRSVP(uint256 eventId) external validEvent(eventId) notEmergencyStopped nonReentrant {
        EventInvite storage eventData = _events[eventId];

        require(eventData.attendees[msg.sender], "Not RSVP'd for this event");
        require(block.timestamp < eventData.eventDate, "Event has already started");

        uint256 tokenId = eventData.attendeeTokens[msg.sender];

        // Burn NFT ticket
        _burn(tokenId);

        // Update event data
        eventData.attendees[msg.sender] = false;
        eventData.attendeeTokens[msg.sender] = 0;
        eventData.currentAttendees = eventData.currentAttendees - 1;

        emit RSVPCancelled(eventId, msg.sender);
    }

    /**
     * @dev Cancel an event (only by event creator or owner)
     * @param eventId ID of the event
     */
    function cancelEvent(uint256 eventId) external {
        require(_events[eventId].eventId != 0, "Event does not exist");
        require(msg.sender == owner() || _authorizedBrands[msg.sender], "Not authorized");

        _events[eventId].isCancelled = true;
        _events[eventId].isActive = false;

        emit EventCancelled(eventId);
    }

    // ============ PRODUCT LAUNCH MANAGEMENT ============

    /**
     * @dev Create a new product launch
     * @param productName Name of the product
     * @param productDescription Description of the product
     * @param launchDate Unix timestamp of the launch
     * @param earlyAccessEndDate Unix timestamp when early access ends
     * @param maxEarlyAccess Maximum number of early access users
     * @param ipfsCID IPFS CID containing launch metadata
     */
    function createProductLaunch(
        string memory productName,
        string memory productDescription,
        uint256 launchDate,
        uint256 earlyAccessEndDate,
        uint256 maxEarlyAccess,
        string memory ipfsCID
    ) external onlyAuthorizedBrand notEmergencyStopped returns (uint256) {
        require(bytes(productName).length > 0, "Product name cannot be empty");
        require(launchDate > block.timestamp, "Launch date must be in the future");
        require(earlyAccessEndDate > block.timestamp && earlyAccessEndDate <= launchDate, "Invalid early access end date");
        require(maxEarlyAccess > 0, "Max early access must be greater than 0");
        require(bytes(ipfsCID).length > 0, "IPFS CID cannot be empty");

        _launchIds = _launchIds + 1;
        uint256 launchId = _launchIds;

        ProductLaunch storage newLaunch = _launches[launchId];
        newLaunch.launchId = launchId;
        newLaunch.productName = productName;
        newLaunch.productDescription = productDescription;
        newLaunch.launchDate = launchDate;
        newLaunch.earlyAccessEndDate = earlyAccessEndDate;
        newLaunch.ipfsCID = ipfsCID;
        newLaunch.isActive = true;
        newLaunch.isLaunched = false;
        newLaunch.maxEarlyAccess = maxEarlyAccess;
        newLaunch.currentEarlyAccess = 0;

        emit ProductLaunchCreated(launchId, productName, launchDate, ipfsCID);
        return launchId;
    }

    /**
     * @dev Grant early access to a user
     * @param launchId ID of the launch
     * @param user Address of the user to grant access to
     */
    function grantEarlyAccess(uint256 launchId, address user) external validLaunch(launchId) notEmergencyStopped nonReentrant {
        require(user != address(0), "Invalid user address");

        ProductLaunch storage launch = _launches[launchId];

        require(block.timestamp < launch.earlyAccessEndDate, "Early access period ended");
        require(!launch.earlyAccessUsers[user], "User already has early access");
        require(launch.currentEarlyAccess < launch.maxEarlyAccess, "Early access limit reached");

        // Mint early access token
        _tokenIds = _tokenIds + 1;
        uint256 tokenId = _tokenIds;

        _safeMint(user, tokenId);

        // Update launch data
        launch.earlyAccessUsers[user] = true;
        launch.currentEarlyAccess = launch.currentEarlyAccess + 1;

        // Set token type and reference
        _tokenTypes[tokenId] = TokenType.PRODUCT_LAUNCH;
        _tokenReferences[tokenId] = launchId;

        emit EarlyAccessGranted(launchId, user, tokenId);
    }

    /**
     * @dev Place a pre-order for a product launch
     * @param launchId ID of the launch
     */
    function placePreOrder(uint256 launchId) external payable validLaunch(launchId) notEmergencyStopped nonReentrant {
        require(msg.value > 0, "Must send ETH for pre-order");

        ProductLaunch storage launch = _launches[launchId];

        require(block.timestamp < launch.launchDate, "Launch has already started");
        require(launch.preOrders[msg.sender] == 0, "Already placed pre-order");

        // Calculate platform fee
        uint256 platformFeeAmount = (msg.value * _platformFee) / FEE_DENOMINATOR;
        uint256 remainingAmount = msg.value - platformFeeAmount;

        // Update pre-order data
        launch.preOrders[msg.sender] = msg.value;

        // Transfer platform fee to owner
        if (platformFeeAmount > 0) {
            (bool success, ) = payable(owner()).call{value: platformFeeAmount}("");
            require(success, "Platform fee transfer failed");
        }

        emit PreOrderPlaced(launchId, msg.sender, msg.value);
    }

    // ============ DIGITAL PRODUCT PASSPORT MANAGEMENT ============

    /**
     * @dev Create a new Digital Product Passport
     * @param productId Product identifier
     * @param brandId Brand identifier
     * @param ipfsCID IPFS CID containing DPP metadata
     * @param metadataHash Hash of the metadata for integrity verification
     */
    function createDPP(
        string memory productId,
        string memory brandId,
        string memory ipfsCID,
        string memory metadataHash
    ) external onlyAuthorizedBrand notEmergencyStopped returns (uint256) {
        require(bytes(productId).length > 0, "Product ID cannot be empty");
        require(bytes(brandId).length > 0, "Brand ID cannot be empty");
        require(bytes(ipfsCID).length > 0, "IPFS CID cannot be empty");
        require(bytes(metadataHash).length > 0, "Metadata hash cannot be empty");

        _dppIds = _dppIds + 1;
        uint256 dppId = _dppIds;

        DigitalProductPassport storage newDPP = _dpps[dppId];
        newDPP.dppId = dppId;
        newDPP.productId = productId;
        newDPP.brandId = brandId;
        newDPP.ipfsCID = ipfsCID;
        newDPP.timestamp = block.timestamp;
        newDPP.isValid = true;
        newDPP.creator = msg.sender;
        newDPP.metadataHash = metadataHash;

        emit DPPCreated(dppId, productId, brandId, ipfsCID);
        return dppId;
    }

    /**
     * @dev Invalidate a Digital Product Passport
     * @param dppId ID of the DPP
     */
    function invalidateDPP(uint256 dppId) external {
        require(_dpps[dppId].dppId != 0, "DPP does not exist");
        require(msg.sender == _dpps[dppId].creator || msg.sender == owner(), "Not authorized");

        _dpps[dppId].isValid = false;

        emit DPPInvalidated(dppId);
    }

    // ============ DIGITAL ART DROP MANAGEMENT ============

    /**
     * @dev Create a new digital art drop
     * @param artistName Name of the artist
     * @param artworkTitle Title of the artwork
     * @param edition Edition number
     * @param maxEditions Maximum number of editions (0 for unlimited)
     * @param ipfsCID IPFS CID containing artwork metadata
     */
    function createArtDrop(
        string memory artistName,
        string memory artworkTitle,
        uint256 edition,
        uint256 maxEditions,
        string memory ipfsCID
    ) external onlyAuthorizedBrand notEmergencyStopped returns (uint256) {
        require(bytes(artistName).length > 0, "Artist name cannot be empty");
        require(bytes(artworkTitle).length > 0, "Artwork title cannot be empty");
        require(edition > 0, "Edition must be greater than 0");
        require(bytes(ipfsCID).length > 0, "IPFS CID cannot be empty");

        _dropIds = _dropIds + 1;
        uint256 dropId = _dropIds;

        DigitalArtDrop storage newDrop = _drops[dropId];
        newDrop.dropId = dropId;
        newDrop.artistName = artistName;
        newDrop.artworkTitle = artworkTitle;
        newDrop.edition = edition;
        newDrop.maxEditions = maxEditions;
        newDrop.ipfsCID = ipfsCID;
        newDrop.isActive = true;
        newDrop.isLimited = maxEditions > 0;

        emit ArtDropCreated(dropId, artistName, artworkTitle, ipfsCID);
        return dropId;
    }

    /**
     * @dev Airdrop artwork to eligible users
     * @param dropId ID of the drop
     * @param recipients Array of recipient addresses
     */
    function airdropArtwork(uint256 dropId, address[] memory recipients) external onlyAuthorizedOperator notEmergencyStopped {
        DigitalArtDrop storage drop = _drops[dropId];
        require(drop.dropId != 0, "Drop does not exist");
        require(drop.isActive, "Drop is not active");

        for (uint256 i = 0; i < recipients.length; i++) {
            address recipient = recipients[i];
            require(recipient != address(0), "Invalid recipient address");
            require(!drop.airdroppedTo[recipient], "Already airdropped to this address");

            if (drop.isLimited) {
                // Count current airdrops by checking existing tokens
                uint256 currentAirdrops = 0;
                for (uint256 j = 1; j <= _tokenIds; j++) {
                    if (_tokenTypes[j] == TokenType.DIGITAL_ART && _tokenReferences[j] == dropId) {
                        currentAirdrops++;
                    }
                }
                require(currentAirdrops < drop.maxEditions, "Max editions reached");
            }

            // Mint NFT
            _tokenIds = _tokenIds + 1;
            uint256 tokenId = _tokenIds;

            _safeMint(recipient, tokenId);

            // Update drop data
            drop.airdroppedTo[recipient] = true;

            // Set token type and reference
            _tokenTypes[tokenId] = TokenType.DIGITAL_ART;
            _tokenReferences[tokenId] = dropId;

            emit ArtAirdropped(dropId, recipient, tokenId);
        }
    }

    // ============ OFFER MANAGEMENT ============

    /**
     * @dev Create a new offer
     * @param title Title of the offer
     * @param discountPercentage Discount percentage (in basis points)
     * @param validFrom Unix timestamp when offer becomes valid
     * @param validUntil Unix timestamp when offer expires
     * @param productScope Scope of products the offer applies to
     * @param conditions Conditions for the offer
     * @param ipfsCID IPFS CID containing offer metadata
     * @param isMerkleBased Whether the offer uses Merkle tree for eligibility
     * @param merkleRoot Merkle root for eligible users (if applicable)
     * @param maxRedemptions Maximum number of redemptions (0 for unlimited)
     */
    function createOffer(
        string memory title,
        uint256 discountPercentage,
        uint256 validFrom,
        uint256 validUntil,
        string memory productScope,
        string memory conditions,
        string memory ipfsCID,
        bool isMerkleBased,
        bytes32 merkleRoot,
        uint256 maxRedemptions
    ) external onlyAuthorizedBrand notEmergencyStopped returns (uint256) {
        require(bytes(title).length > 0, "Title cannot be empty");
        require(discountPercentage > 0 && discountPercentage <= 10000, "Invalid discount percentage");
        require(validFrom < validUntil, "Invalid validity period");
        require(validUntil > block.timestamp, "Offer expires in the past");
        require(bytes(ipfsCID).length > 0, "IPFS CID cannot be empty");

        _offerIds = _offerIds + 1;
        uint256 offerId = _offerIds;

        Offer storage newOffer = _offers[offerId];
        newOffer.offerId = offerId;
        newOffer.title = title;
        newOffer.discountPercentage = discountPercentage;
        newOffer.validFrom = validFrom;
        newOffer.validUntil = validUntil;
        newOffer.productScope = productScope;
        newOffer.conditions = conditions;
        newOffer.ipfsCID = ipfsCID;
        newOffer.isActive = true;
        newOffer.isMerkleBased = isMerkleBased;
        newOffer.merkleRoot = merkleRoot;
        newOffer.maxRedemptions = maxRedemptions;
        newOffer.currentRedemptions = 0;

        emit OfferCreated(offerId, title, discountPercentage, ipfsCID);
        return offerId;
    }

    /**
     * @dev Redeem an offer
     * @param offerId ID of the offer
     * @param merkleProof Merkle proof for eligibility (if applicable)
     */
    function redeemOffer(uint256 offerId, bytes32[] memory merkleProof) external validOffer(offerId) notEmergencyStopped nonReentrant {
        Offer storage offer = _offers[offerId];

        require(!offer.redeemedBy[msg.sender], "Offer already redeemed");

        if (offer.isMerkleBased) {
            bytes32 leaf = keccak256(abi.encodePacked(msg.sender));
            require(MerkleProof.verify(merkleProof, offer.merkleRoot, leaf), "Not eligible for this offer");
        }

        if (offer.maxRedemptions > 0) {
            require(offer.currentRedemptions < offer.maxRedemptions, "Offer redemption limit reached");
        }

        // Mint offer NFT
        _tokenIds = _tokenIds + 1;
        uint256 tokenId = _tokenIds;

        _safeMint(msg.sender, tokenId);

        // Update offer data
        offer.redeemedBy[msg.sender] = true;
        offer.userRedemptions[msg.sender] = offer.userRedemptions[msg.sender] + 1;
        offer.currentRedemptions = offer.currentRedemptions + 1;

        // Set token type and reference
        _tokenTypes[tokenId] = TokenType.OFFER_COUPON;
        _tokenReferences[tokenId] = offerId;

        emit OfferRedeemed(offerId, msg.sender);
    }

    /**
     * @dev Check if an offer is expired and mark it as inactive
     * @param offerId ID of the offer
     */
    function checkOfferExpiration(uint256 offerId) external {
        Offer storage offer = _offers[offerId];
        require(offer.offerId != 0, "Offer does not exist");

        if (block.timestamp > offer.validUntil && offer.isActive) {
            offer.isActive = false;
            emit OfferExpired(offerId);
        }
    }

    // ============ ACCESS CONTROL FUNCTIONS ============

    /**
     * @dev Authorize a brand address
     * @param brand Address of the brand to authorize
     */
    function authorizeBrand(address brand) external onlyOwner {
        require(brand != address(0), "Invalid brand address");
        require(!_authorizedBrands[brand], "Brand already authorized");

        _authorizedBrands[brand] = true;
        emit BrandAuthorized(brand);
    }

    /**
     * @dev Revoke brand authorization
     * @param brand Address of the brand to revoke
     */
    function revokeBrand(address brand) external onlyOwner {
        require(_authorizedBrands[brand], "Brand not authorized");

        _authorizedBrands[brand] = false;
        emit BrandRevoked(brand);
    }

    /**
     * @dev Authorize an operator address
     * @param operator Address of the operator to authorize
     */
    function authorizeOperator(address operator) external onlyOwner {
        require(operator != address(0), "Invalid operator address");
        require(!_authorizedOperators[operator], "Operator already authorized");

        _authorizedOperators[operator] = true;
        emit OperatorAuthorized(operator);
    }

    /**
     * @dev Revoke operator authorization
     * @param operator Address of the operator to revoke
     */
    function revokeOperator(address operator) external onlyOwner {
        require(_authorizedOperators[operator], "Operator not authorized");

        _authorizedOperators[operator] = false;
        emit OperatorRevoked(operator);
    }

    /**
     * @dev Update platform fee
     * @param newFee New platform fee in basis points
     */
    function updatePlatformFee(uint256 newFee) external onlyOwner {
        require(newFee <= 1000, "Fee cannot exceed 10%");
        _platformFee = newFee;
    }

    /**
     * @dev Activate emergency stop
     */
    function activateEmergencyStop() external onlyOwner {
        require(!_emergencyStop, "Emergency stop already active");
        _emergencyStop = true;
        emit EmergencyStopActivated();
    }

    /**
     * @dev Deactivate emergency stop
     */
    function deactivateEmergencyStop() external onlyOwner {
        require(_emergencyStop, "Emergency stop not active");
        _emergencyStop = false;
        emit EmergencyStopDeactivated();
    }



    // ============ EMERGENCY FUNCTIONS ============

    /**
     * @dev Emergency function to recover stuck ETH
     * @param to Address to send ETH to
     * @param amount Amount to recover
     */
    function emergencyRecoverETH(address to, uint256 amount) external onlyOwner {
        require(to != address(0), "Invalid recipient");
        require(amount > 0, "Amount must be greater than 0");
        require(amount <= address(this).balance, "Insufficient balance");

        (bool success, ) = payable(to).call{value: amount}("");
        require(success, "Transfer failed");
    }

    // ============ RECEIVE FUNCTION ============

    receive() external payable {
        // Contract can receive ETH for fees and pre-orders
    }
}

contracts/TrataTechMainUpgradeable.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts-upgradeable/token/ERC721/ERC721Upgradeable.sol";
import "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/PausableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/ReentrancyGuardUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/metatx/ERC2771ContextUpgradeable.sol";

import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import "@openzeppelin/contracts/utils/cryptography/MerkleProof.sol";
import "@openzeppelin/contracts/utils/Strings.sol";

/**
 * @title TrataTechMainUpgradeable
 * @dev Upgradeable and gasless version of TrataTech platform handling:
 * - Event Invites & RSVP
 * - Product Launches & Early Access
 * - Digital Product Passports
 * - Digital Art Drops
 * - Offers & Coupons
 * @author Advanced Developer
 */
contract TrataTechMainUpgradeable is 
    Initializable,
    ERC721Upgradeable,
    OwnableUpgradeable,
    PausableUpgradeable,
    ReentrancyGuardUpgradeable,
    UUPSUpgradeable,
    ERC2771ContextUpgradeable
{
    using ECDSA for bytes32;
    using Strings for uint256;

    // ============ STRUCTS ============

    struct EventInvite {
        uint256 eventId;
        string eventName;
        string eventDescription;
        uint256 eventDate;
        uint256 maxAttendees;
        uint256 currentAttendees;
        string ipfsCID;
        bool isActive;
        bool isCancelled;
        mapping(address => bool) attendees;
        mapping(address => uint256) attendeeTokens;
    }

    struct ProductLaunch {
        uint256 launchId;
        string productName;
        string productDescription;
        uint256 launchDate;
        uint256 earlyAccessEndDate;
        string ipfsCID;
        bool isActive;
        bool isLaunched;
        uint256 maxEarlyAccess;
        uint256 currentEarlyAccess;
        mapping(address => bool) earlyAccessUsers;
        mapping(address => bool) preOrders;
    }

    struct DigitalProductPassport {
        uint256 dppId;
        string productId;
        string brandId;
        string ipfsCID;
        uint256 timestamp;
        bool isValid;
        address creator;
        string metadataHash;
    }

    struct DigitalArtDrop {
        uint256 dropId;
        string artistName;
        string artworkTitle;
        uint256 edition;
        uint256 maxEditions;
        string ipfsCID;
        bool isActive;
        bool isLimited;
        uint256 currentAirdrops; // Track count to avoid loop
        mapping(address => bool) airdroppedTo;
    }

    struct Offer {
        uint256 offerId;
        string title;
        uint256 discountPercentage;
        uint256 validFrom;
        uint256 validUntil;
        string productScope;
        string conditions;
        string ipfsCID;
        bool isActive;
        bool isMerkleBased;
        bytes32 merkleRoot;
        uint256 maxRedemptions;
        uint256 currentRedemptions;
        mapping(address => bool) redeemedBy;
        mapping(address => uint256) userRedemptions;
    }

    // ============ STATE VARIABLES ============

    uint256 private _tokenIds;
    uint256 private _eventIds;
    uint256 private _launchIds;
    uint256 private _dppIds;
    uint256 private _dropIds;
    uint256 private _offerIds;

    // Mappings
    mapping(uint256 => EventInvite) private _events;
    mapping(uint256 => ProductLaunch) private _launches;
    mapping(uint256 => DigitalProductPassport) private _dpps;
    mapping(uint256 => DigitalArtDrop) private _drops;
    mapping(uint256 => Offer) private _offers;

    // Token type mapping
    mapping(uint256 => TokenType) private _tokenTypes;
    mapping(uint256 => uint256) private _tokenReferences;

    // Access control
    mapping(address => bool) private _authorizedBrands;
    mapping(address => bool) private _authorizedOperators;

    // Reserved for future use
    uint256[50] private __gap;

    // Emergency controls
    bool private _emergencyStop;

    // ============ ENUMS ============

    enum TokenType {
        EVENT_INVITE,
        PRODUCT_LAUNCH,
        DIGITAL_ART,
        OFFER_COUPON,
        DPP_PASSPORT
    }

    // ============ EVENTS ============

    event EventCreated(uint256 indexed eventId, string eventName, uint256 eventDate, string ipfsCID);
    event EventCancelled(uint256 indexed eventId);
    event RSVPSubmitted(uint256 indexed eventId, address indexed attendee, uint256 tokenId);
    event RSVPCancelled(uint256 indexed eventId, address indexed attendee);

    event ProductLaunchCreated(uint256 indexed launchId, string productName, uint256 launchDate, string ipfsCID);
    event EarlyAccessGranted(uint256 indexed launchId, address indexed user, uint256 tokenId);
    event PreOrderPlaced(uint256 indexed launchId, address indexed user, uint256 amount);

    event DPPCreated(uint256 indexed dppId, string productId, string brandId, string ipfsCID);
    event DPPInvalidated(uint256 indexed dppId);

    event ArtDropCreated(uint256 indexed dropId, string artistName, string artworkTitle, string ipfsCID);
    event ArtAirdropped(uint256 indexed dropId, address indexed recipient, uint256 tokenId);

    event OfferCreated(uint256 indexed offerId, string title, uint256 discountPercentage, string ipfsCID);
    event OfferRedeemed(uint256 indexed offerId, address indexed user);
    event OfferExpired(uint256 indexed offerId);

    event BrandAuthorized(address indexed brand);
    event BrandRevoked(address indexed brand);
    event OperatorAuthorized(address indexed operator);
    event OperatorRevoked(address indexed operator);
    event EmergencyStopActivated();
    event EmergencyStopDeactivated();

    // Batch operation limits
    uint256 public constant MAX_AIRDROP_RECIPIENTS = 50;

    // Duplicate gap removed

    // ============ MODIFIERS ============

    modifier onlyAuthorizedBrand() {
        require(_authorizedBrands[_msgSender()] || _msgSender() == owner(), "Not authorized brand");
        _;
    }

    modifier onlyAuthorizedOperator() {
        require(_authorizedOperators[_msgSender()] || _msgSender() == owner(), "Not authorized operator");
        _;
    }

    modifier notEmergencyStopped() {
        require(!_emergencyStop, "Contract is emergency stopped");
        _;
    }

    modifier validEvent(uint256 eventId) {
        require(_events[eventId].eventId != 0, "Event does not exist");
        require(_events[eventId].isActive, "Event is not active");
        require(!_events[eventId].isCancelled, "Event is cancelled");
        _;
    }

    modifier validLaunch(uint256 launchId) {
        require(_launches[launchId].launchId != 0, "Launch does not exist");
        require(_launches[launchId].isActive, "Launch is not active");
        _;
    }

    modifier validOffer(uint256 offerId) {
        require(_offers[offerId].offerId != 0, "Offer does not exist");
        require(_offers[offerId].isActive, "Offer is not active");
        require(block.timestamp >= _offers[offerId].validFrom, "Offer not yet valid");
        require(block.timestamp <= _offers[offerId].validUntil, "Offer expired");
        _;
    }

    // ============ INITIALIZATION ============

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor(address trustedForwarder) ERC2771ContextUpgradeable(trustedForwarder) {
        require(trustedForwarder != address(0), "TrataTech: Invalid trusted forwarder");
        _disableInitializers();
    }

    function initialize(address initialOwner, address trustedForwarder) public initializer {
        __ERC721_init("TrataTech Platform", "TRATA");
        __Ownable_init(initialOwner);
        __Pausable_init();
        __ReentrancyGuard_init();
        __UUPSUpgradeable_init();
        // ERC2771Context initialization removed - constructor handles this

        _tokenIds = 1; // Start from 1
        // Platform fee removed - no blockchain payments
    }

    // ============ UUPS UPGRADE AUTHORIZATION ============

    function _authorizeUpgrade(address newImplementation) internal override onlyOwner {}

    // ============ ERC2771 OVERRIDES FOR GASLESS ============

    function _msgSender() internal view virtual override(ContextUpgradeable, ERC2771ContextUpgradeable) returns (address) {
        return ERC2771ContextUpgradeable._msgSender();
    }

    function _msgData() internal view virtual override(ContextUpgradeable, ERC2771ContextUpgradeable) returns (bytes calldata) {
        return ERC2771ContextUpgradeable._msgData();
    }

    function _contextSuffixLength() internal view virtual override(ContextUpgradeable, ERC2771ContextUpgradeable) returns (uint256) {
        return ERC2771ContextUpgradeable._contextSuffixLength();
    }

    // ============ GETTER FUNCTIONS ============

    function events(uint256 eventId) external view returns (
        uint256 eventId_,
        string memory eventName,
        string memory eventDescription,
        uint256 eventDate,
        uint256 maxAttendees,
        uint256 currentAttendees,
        string memory ipfsCID,
        bool isActive,
        bool isCancelled
    ) {
        EventInvite storage eventData = _events[eventId];
        return (
            eventData.eventId,
            eventData.eventName,
            eventData.eventDescription,
            eventData.eventDate,
            eventData.maxAttendees,
            eventData.currentAttendees,
            eventData.ipfsCID,
            eventData.isActive,
            eventData.isCancelled
        );
    }

    function launches(uint256 launchId) external view returns (
        uint256 launchId_,
        string memory productName,
        string memory productDescription,
        uint256 launchDate,
        uint256 earlyAccessEndDate,
        string memory ipfsCID,
        bool isActive,
        bool isLaunched,
        uint256 maxEarlyAccess,
        uint256 currentEarlyAccess
    ) {
        ProductLaunch storage launch = _launches[launchId];
        return (
            launch.launchId,
            launch.productName,
            launch.productDescription,
            launch.launchDate,
            launch.earlyAccessEndDate,
            launch.ipfsCID,
            launch.isActive,
            launch.isLaunched,
            launch.maxEarlyAccess,
            launch.currentEarlyAccess
        );
    }

    function offers(uint256 offerId) external view returns (
        uint256 offerId_,
        string memory title,
        uint256 discountPercentage,
        uint256 validFrom,
        uint256 validUntil,
        string memory productScope,
        string memory conditions,
        string memory ipfsCID,
        bool isActive,
        bool isMerkleBased,
        bytes32 merkleRoot,
        uint256 maxRedemptions,
        uint256 currentRedemptions
    ) {
        Offer storage offer = _offers[offerId];
        return (
            offer.offerId,
            offer.title,
            offer.discountPercentage,
            offer.validFrom,
            offer.validUntil,
            offer.productScope,
            offer.conditions,
            offer.ipfsCID,
            offer.isActive,
            offer.isMerkleBased,
            offer.merkleRoot,
            offer.maxRedemptions,
            offer.currentRedemptions
        );
    }

    function tokenTypes(uint256 tokenId) external view returns (TokenType) {
        return _tokenTypes[tokenId];
    }

    function tokenReferences(uint256 tokenId) external view returns (uint256) {
        return _tokenReferences[tokenId];
    }

    function authorizedBrands(address brand) external view returns (bool) {
        return _authorizedBrands[brand];
    }

    function authorizedOperators(address operator) external view returns (bool) {
        return _authorizedOperators[operator];
    }

    // Platform fee function removed - no blockchain payments

    function emergencyStop() external view returns (bool) {
        return _emergencyStop;
    }

    // ============ EVENT MANAGEMENT ============

    function createEventInvite(
        string memory eventName,
        string memory eventDescription,
        uint256 eventDate,
        uint256 maxAttendees,
        string memory ipfsCID
    ) external onlyAuthorizedBrand notEmergencyStopped returns (uint256) {
        require(bytes(eventName).length > 0, "Event name cannot be empty");
        require(eventDate > block.timestamp, "Event date must be in the future");
        require(maxAttendees > 0, "Max attendees must be greater than 0");
        require(bytes(ipfsCID).length > 0, "IPFS CID cannot be empty");

        _eventIds = _eventIds + 1;
        uint256 eventId = _eventIds;

        EventInvite storage newEvent = _events[eventId];
        newEvent.eventId = eventId;
        newEvent.eventName = eventName;
        newEvent.eventDescription = eventDescription;
        newEvent.eventDate = eventDate;
        newEvent.maxAttendees = maxAttendees;
        newEvent.currentAttendees = 0;
        newEvent.ipfsCID = ipfsCID;
        newEvent.isActive = true;
        newEvent.isCancelled = false;

        emit EventCreated(eventId, eventName, eventDate, ipfsCID);
        return eventId;
    }

    function submitRSVP(uint256 eventId) external validEvent(eventId) notEmergencyStopped nonReentrant {
        EventInvite storage eventData = _events[eventId];

        require(!eventData.attendees[_msgSender()], "Already RSVP'd");
        require(eventData.currentAttendees < eventData.maxAttendees, "Event is full");
        require(block.timestamp < eventData.eventDate, "Event has already started");

        // Mint NFT ticket
        _tokenIds = _tokenIds + 1;
        uint256 tokenId = _tokenIds;

        _safeMint(_msgSender(), tokenId);

        // Update event data
        eventData.attendees[_msgSender()] = true;
        eventData.attendeeTokens[_msgSender()] = tokenId;
        eventData.currentAttendees = eventData.currentAttendees + 1;

        // Set token type and reference
        _tokenTypes[tokenId] = TokenType.EVENT_INVITE;
        _tokenReferences[tokenId] = eventId;

        emit RSVPSubmitted(eventId, _msgSender(), tokenId);
    }

    function cancelRSVP(uint256 eventId) external validEvent(eventId) notEmergencyStopped nonReentrant {
        EventInvite storage eventData = _events[eventId];

        require(eventData.attendees[_msgSender()], "Not RSVP'd for this event");
        require(block.timestamp < eventData.eventDate, "Event has already started");

        uint256 tokenId = eventData.attendeeTokens[_msgSender()];

        // Burn NFT ticket
        _burn(tokenId);

        // Update event data
        eventData.attendees[_msgSender()] = false;
        eventData.attendeeTokens[_msgSender()] = 0;
        eventData.currentAttendees = eventData.currentAttendees - 1;

        emit RSVPCancelled(eventId, _msgSender());
    }

    function cancelEvent(uint256 eventId) external {
        require(_events[eventId].eventId != 0, "Event does not exist");
        require(_msgSender() == owner() || _authorizedBrands[_msgSender()], "Not authorized");

        _events[eventId].isCancelled = true;
        _events[eventId].isActive = false;

        emit EventCancelled(eventId);
    }

    // ============ PRODUCT LAUNCH MANAGEMENT ============

    function createProductLaunch(
        string memory productName,
        string memory productDescription,
        uint256 launchDate,
        uint256 earlyAccessEndDate,
        uint256 maxEarlyAccess,
        string memory ipfsCID
    ) external onlyAuthorizedBrand notEmergencyStopped returns (uint256) {
        require(bytes(productName).length > 0, "Product name cannot be empty");
        require(launchDate > block.timestamp, "Launch date must be in the future");
        require(earlyAccessEndDate > block.timestamp && earlyAccessEndDate <= launchDate, "Invalid early access end date");
        require(maxEarlyAccess > 0, "Max early access must be greater than 0");
        require(bytes(ipfsCID).length > 0, "IPFS CID cannot be empty");

        _launchIds = _launchIds + 1;
        uint256 launchId = _launchIds;

        ProductLaunch storage newLaunch = _launches[launchId];
        newLaunch.launchId = launchId;
        newLaunch.productName = productName;
        newLaunch.productDescription = productDescription;
        newLaunch.launchDate = launchDate;
        newLaunch.earlyAccessEndDate = earlyAccessEndDate;
        newLaunch.ipfsCID = ipfsCID;
        newLaunch.isActive = true;
        newLaunch.isLaunched = false;
        newLaunch.maxEarlyAccess = maxEarlyAccess;
        newLaunch.currentEarlyAccess = 0;

        emit ProductLaunchCreated(launchId, productName, launchDate, ipfsCID);
        return launchId;
    }

    function grantEarlyAccess(uint256 launchId, address user) external validLaunch(launchId) notEmergencyStopped nonReentrant {
        require(user != address(0), "Invalid user address");

        ProductLaunch storage launch = _launches[launchId];

        require(block.timestamp < launch.earlyAccessEndDate, "Early access period ended");
        require(!launch.earlyAccessUsers[user], "User already has early access");
        require(launch.currentEarlyAccess < launch.maxEarlyAccess, "Early access limit reached");

        // Mint early access token
        _tokenIds = _tokenIds + 1;
        uint256 tokenId = _tokenIds;

        _safeMint(user, tokenId);

        // Update launch data
        launch.earlyAccessUsers[user] = true;
        launch.currentEarlyAccess = launch.currentEarlyAccess + 1;

        // Set token type and reference
        _tokenTypes[tokenId] = TokenType.PRODUCT_LAUNCH;
        _tokenReferences[tokenId] = launchId;

        emit EarlyAccessGranted(launchId, user, tokenId);
    }

    function placePreOrder(uint256 launchId) external validLaunch(launchId) notEmergencyStopped nonReentrant {
        ProductLaunch storage launch = _launches[launchId];

        require(block.timestamp < launch.launchDate, "Launch has already started");
        require(!launch.preOrders[_msgSender()], "Already placed pre-order");

        // Update pre-order data
        launch.preOrders[_msgSender()] = true;

        emit PreOrderPlaced(launchId, _msgSender(), 0);
    }

    // ============ DIGITAL PRODUCT PASSPORT MANAGEMENT ============

    function createDPP(
        string memory productId,
        string memory brandId,
        string memory ipfsCID,
        string memory metadataHash
    ) external onlyAuthorizedBrand notEmergencyStopped returns (uint256) {
        require(bytes(productId).length > 0, "Product ID cannot be empty");
        require(bytes(brandId).length > 0, "Brand ID cannot be empty");
        require(bytes(ipfsCID).length > 0, "IPFS CID cannot be empty");
        require(bytes(metadataHash).length > 0, "Metadata hash cannot be empty");

        _dppIds = _dppIds + 1;
        uint256 dppId = _dppIds;

        DigitalProductPassport storage newDPP = _dpps[dppId];
        newDPP.dppId = dppId;
        newDPP.productId = productId;
        newDPP.brandId = brandId;
        newDPP.ipfsCID = ipfsCID;
        newDPP.timestamp = block.timestamp;
        newDPP.isValid = true;
        newDPP.creator = _msgSender();
        newDPP.metadataHash = metadataHash;

        emit DPPCreated(dppId, productId, brandId, ipfsCID);
        return dppId;
    }

    function invalidateDPP(uint256 dppId) external {
        require(_dpps[dppId].dppId != 0, "DPP does not exist");
        require(_msgSender() == _dpps[dppId].creator || _msgSender() == owner(), "Not authorized");

        _dpps[dppId].isValid = false;

        emit DPPInvalidated(dppId);
    }

    // ============ DIGITAL ART DROP MANAGEMENT ============

    function createArtDrop(
        string memory artistName,
        string memory artworkTitle,
        uint256 edition,
        uint256 maxEditions,
        string memory ipfsCID
    ) external onlyAuthorizedBrand notEmergencyStopped returns (uint256) {
        require(bytes(artistName).length > 0, "Artist name cannot be empty");
        require(bytes(artworkTitle).length > 0, "Artwork title cannot be empty");
        require(edition > 0, "Edition must be greater than 0");
        require(bytes(ipfsCID).length > 0, "IPFS CID cannot be empty");

        _dropIds = _dropIds + 1;
        uint256 dropId = _dropIds;

        DigitalArtDrop storage newDrop = _drops[dropId];
        newDrop.dropId = dropId;
        newDrop.artistName = artistName;
        newDrop.artworkTitle = artworkTitle;
        newDrop.edition = edition;
        newDrop.maxEditions = maxEditions;
        newDrop.ipfsCID = ipfsCID;
        newDrop.isActive = true;
        newDrop.isLimited = maxEditions > 0;
        newDrop.currentAirdrops = 0;

        emit ArtDropCreated(dropId, artistName, artworkTitle, ipfsCID);
        return dropId;
    }

    function airdropArtwork(uint256 dropId, address[] memory recipients) external onlyAuthorizedOperator notEmergencyStopped {
        require(recipients.length <= MAX_AIRDROP_RECIPIENTS, "Too many recipients");
        require(recipients.length > 0, "No recipients provided");

        DigitalArtDrop storage drop = _drops[dropId];
        require(drop.dropId != 0, "Drop does not exist");
        require(drop.isActive, "Drop is not active");

        for (uint256 i = 0; i < recipients.length; i++) {
            address recipient = recipients[i];
            require(recipient != address(0), "Invalid recipient address");
            require(!drop.airdroppedTo[recipient], "Already airdropped to this address");

            if (drop.isLimited) {
                // Use counter instead of loop to prevent DoS
                require(drop.currentAirdrops < drop.maxEditions, "Max editions reached");
            }

            // Mint NFT
            _tokenIds = _tokenIds + 1;
            uint256 tokenId = _tokenIds;

            _safeMint(recipient, tokenId);

            // Update drop data
            drop.airdroppedTo[recipient] = true;
            if (drop.isLimited) {
                drop.currentAirdrops++;
            }

            // Set token type and reference
            _tokenTypes[tokenId] = TokenType.DIGITAL_ART;
            _tokenReferences[tokenId] = dropId;

            emit ArtAirdropped(dropId, recipient, tokenId);
        }
    }

    // ============ OFFER MANAGEMENT ============

    function createOffer(
        string memory title,
        uint256 discountPercentage,
        uint256 validFrom,
        uint256 validUntil,
        string memory productScope,
        string memory conditions,
        string memory ipfsCID,
        bool isMerkleBased,
        bytes32 merkleRoot,
        uint256 maxRedemptions
    ) external onlyAuthorizedBrand notEmergencyStopped returns (uint256) {
        require(bytes(title).length > 0, "Title cannot be empty");
        require(discountPercentage > 0 && discountPercentage <= 10000, "Invalid discount percentage");
        require(validFrom < validUntil, "Invalid validity period");
        require(validUntil > block.timestamp, "Offer expires in the past");
        require(bytes(ipfsCID).length > 0, "IPFS CID cannot be empty");

        _offerIds = _offerIds + 1;
        uint256 offerId = _offerIds;

        Offer storage newOffer = _offers[offerId];
        newOffer.offerId = offerId;
        newOffer.title = title;
        newOffer.discountPercentage = discountPercentage;
        newOffer.validFrom = validFrom;
        newOffer.validUntil = validUntil;
        newOffer.productScope = productScope;
        newOffer.conditions = conditions;
        newOffer.ipfsCID = ipfsCID;
        newOffer.isActive = true;
        newOffer.isMerkleBased = isMerkleBased;
        newOffer.merkleRoot = merkleRoot;
        newOffer.maxRedemptions = maxRedemptions;
        newOffer.currentRedemptions = 0;

        emit OfferCreated(offerId, title, discountPercentage, ipfsCID);
        return offerId;
    }

    function redeemOffer(uint256 offerId, bytes32[] memory merkleProof) external validOffer(offerId) notEmergencyStopped nonReentrant {
        Offer storage offer = _offers[offerId];

        require(!offer.redeemedBy[_msgSender()], "Offer already redeemed");

        if (offer.isMerkleBased) {
            bytes32 leaf = keccak256(abi.encodePacked(_msgSender()));
            require(MerkleProof.verify(merkleProof, offer.merkleRoot, leaf), "Not eligible for this offer");
        }

        if (offer.maxRedemptions > 0) {
            require(offer.currentRedemptions < offer.maxRedemptions, "Offer redemption limit reached");
        }

        // Mint offer NFT
        _tokenIds = _tokenIds + 1;
        uint256 tokenId = _tokenIds;

        _safeMint(_msgSender(), tokenId);

        // Update offer data
        offer.redeemedBy[_msgSender()] = true;
        offer.userRedemptions[_msgSender()] = offer.userRedemptions[_msgSender()] + 1;
        offer.currentRedemptions = offer.currentRedemptions + 1;

        // Set token type and reference
        _tokenTypes[tokenId] = TokenType.OFFER_COUPON;
        _tokenReferences[tokenId] = offerId;

        emit OfferRedeemed(offerId, _msgSender());
    }

    function checkOfferExpiration(uint256 offerId) external {
        Offer storage offer = _offers[offerId];
        require(offer.offerId != 0, "Offer does not exist");

        if (block.timestamp > offer.validUntil && offer.isActive) {
            offer.isActive = false;
            emit OfferExpired(offerId);
        }
    }

    // ============ ACCESS CONTROL FUNCTIONS ============

    function authorizeBrand(address brand) external onlyOwner {
        require(brand != address(0), "Invalid brand address");
        require(!_authorizedBrands[brand], "Brand already authorized");

        _authorizedBrands[brand] = true;
        emit BrandAuthorized(brand);
    }

    function revokeBrand(address brand) external onlyOwner {
        require(_authorizedBrands[brand], "Brand not authorized");

        _authorizedBrands[brand] = false;
        emit BrandRevoked(brand);
    }

    function authorizeOperator(address operator) external onlyOwner {
        require(operator != address(0), "Invalid operator address");
        require(!_authorizedOperators[operator], "Operator already authorized");

        _authorizedOperators[operator] = true;
        emit OperatorAuthorized(operator);
    }

    function revokeOperator(address operator) external onlyOwner {
        require(_authorizedOperators[operator], "Operator not authorized");

        _authorizedOperators[operator] = false;
        emit OperatorRevoked(operator);
    }

    function updatePlatformFee(uint256 newFee) external onlyOwner {
        require(newFee <= 1000, "Fee cannot exceed 10%");
        // Platform fee setting removed - no fee functionality
    }

    function activateEmergencyStop() external onlyOwner {
        require(!_emergencyStop, "Emergency stop already active");
        _emergencyStop = true;
        emit EmergencyStopActivated();
    }

    function deactivateEmergencyStop() external onlyOwner {
        require(_emergencyStop, "Emergency stop not active");
        _emergencyStop = false;
        emit EmergencyStopDeactivated();
    }

    // ============ PAUSABLE FUNCTIONS ============

    function pause() external onlyOwner {
        _pause();
    }

    function unpause() external onlyOwner {
        _unpause();
    }

    // ============ EMERGENCY FUNCTIONS ============

    // Emergency recovery and receive functions removed - no blockchain payments

    // ============ VERSION FUNCTION ============

    function version() external pure returns (string memory) {
        return "1.0.0";
    }
}

contracts/TrataTechOwnershipRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import "@openzeppelin/contracts/utils/Strings.sol";

/**
 * @title TrataTechOwnershipRegistry
 * @dev Ownership Registry Contract for managing NFT-linked digital deeds and transfer logic
 * @author Advanced Developer
 */
contract TrataTechOwnershipRegistry is ERC721, Ownable, Pausable, ReentrancyGuard {

    using ECDSA for bytes32;
    using Strings for uint256;

    // ============ STRUCTS ============

    struct OwnershipDeed {
        uint256 deedId;
        uint256 passportId;
        address owner;
        uint256 acquisitionDate;
        uint256 acquisitionPrice;
        string acquisitionMethod;
        string ipfsCID;
        string metadataHash;
        bool isValid;
        bool isLocked;
        uint256 lockExpiry;
        address previousOwner;
        mapping(string => string) additionalData;
        string[] dataKeys;
    }

    struct TransferRequest {
        uint256 requestId;
        uint256 deedId;
        address from;
        address to;
        uint256 requestDate;
        uint256 proposedPrice;
        string transferReason;
        TransferStatus status;
        address requester;
        uint256 expiryDate;
        bool isApproved;
        address approver;
    }

    struct RoyaltyInfo {
        address recipient;
        uint256 percentage; // In basis points (e.g., 500 = 5%)
        bool isActive;
    }

    enum TransferStatus {
        PENDING,
        APPROVED,
        REJECTED,
        EXPIRED,
        CANCELLED
    }

    enum TransferType {
        PRIMARY_SALE,
        SECONDARY_SALE,
        GIFT,
        INHERITANCE,
        LOAN,
        CONSIGNMENT,
        AUCTION,
        CUSTOM
    }

    // ============ STATE VARIABLES ============

    uint256 private _deedIds = 0;
    uint256 private _requestIds = 0;

    // Mappings
    mapping(uint256 => OwnershipDeed) public ownershipDeeds;
    mapping(uint256 => TransferRequest) public transferRequests;
    mapping(uint256 => uint256) public passportToDeed;
    mapping(address => uint256[]) public ownerToDeeds;
    mapping(uint256 => RoyaltyInfo) public deedRoyalties;
    mapping(address => bool) public authorizedBrands;
    mapping(address => bool) public authorizedOperators;
    mapping(address => bool) public authorizedTransferAgents;

    // Fee structure
    uint256 public transferFee = 0.005 ether;
    uint256 public royaltyFee = 250; // 2.5% in basis points
    uint256 public constant FEE_DENOMINATOR = 10000;

    // Transfer settings
    uint256 public transferApprovalPeriod = 7 days;
    uint256 public maxTransferRequests = 5;

    // Emergency controls
    bool public emergencyStop = false;

    // ============ EVENTS ============

    event OwnershipDeedCreated(
        uint256 indexed deedId,
        uint256 indexed passportId,
        address indexed owner,
        uint256 acquisitionPrice,
        string acquisitionMethod,
        string ipfsCID
    );

    event OwnershipDeedTransferred(
        uint256 indexed deedId,
        address indexed from,
        address indexed to,
        uint256 transferPrice,
        TransferType transferType
    );

    event TransferRequestCreated(
        uint256 indexed requestId,
        uint256 indexed deedId,
        address indexed from,
        address to,
        uint256 proposedPrice,
        TransferStatus status
    );

    event TransferRequestApproved(
        uint256 indexed requestId,
        address indexed approver
    );

    event TransferRequestRejected(
        uint256 indexed requestId,
        string reason,
        address indexed rejector
    );

    event DeedLocked(
        uint256 indexed deedId,
        uint256 lockExpiry,
        address indexed locker
    );

    event DeedUnlocked(
        uint256 indexed deedId,
        address indexed unlocker
    );

    event RoyaltySet(
        uint256 indexed deedId,
        address indexed recipient,
        uint256 percentage
    );

    event RoyaltyPaid(
        uint256 indexed deedId,
        address indexed recipient,
        uint256 amount
    );

    // ============ MODIFIERS ============

    modifier onlyAuthorizedBrand() {
        require(authorizedBrands[msg.sender] || msg.sender == owner(), "Not authorized brand");
        _;
    }

    modifier onlyAuthorizedOperator() {
        require(authorizedOperators[msg.sender] || msg.sender == owner(), "Not authorized operator");
        _;
    }

    modifier onlyAuthorizedTransferAgent() {
        require(authorizedTransferAgents[msg.sender] || msg.sender == owner(), "Not authorized transfer agent");
        _;
    }

    modifier notEmergencyStopped() {
        require(!emergencyStop, "Contract is emergency stopped");
        _;
    }

    modifier validDeed(uint256 deedId) {
        require(ownershipDeeds[deedId].deedId != 0, "Ownership deed does not exist");
        require(ownershipDeeds[deedId].isValid, "Ownership deed is invalid");
        _;
    }

    modifier onlyDeedOwner(uint256 deedId) {
        require(ownershipDeeds[deedId].owner == msg.sender, "Not deed owner");
        _;
    }

    modifier deedNotLocked(uint256 deedId) {
        require(!ownershipDeeds[deedId].isLocked || ownershipDeeds[deedId].lockExpiry < block.timestamp, "Deed is locked");
        _;
    }

    // ============ CONSTRUCTOR ============

    constructor() ERC721("TrataTech Ownership Deed", "TRATA-DEED") Ownable(msg.sender) {
        _deedIds = 1; // Start from 1
        _requestIds = 1; // Start from 1
    }

    // ============ OWNERSHIP DEED MANAGEMENT ============

    /**
     * @dev Create a new ownership deed (primary sale)
     * @param passportId Product passport ID
     * @param owner Initial owner address
     * @param acquisitionPrice Acquisition price
     * @param acquisitionMethod Method of acquisition
     * @param ipfsCID IPFS CID containing deed metadata
     * @param metadataHash Hash of the metadata for integrity verification
     * @param additionalData Array of key-value pairs for additional data
     */
    function createOwnershipDeed(
        uint256 passportId,
        address owner,
        uint256 acquisitionPrice,
        string memory acquisitionMethod,
        string memory ipfsCID,
        string memory metadataHash,
        string[] memory additionalData
    ) external onlyAuthorizedBrand notEmergencyStopped nonReentrant {
        require(passportId > 0, "Invalid passport ID");
        require(owner != address(0), "Invalid owner address");
        require(bytes(acquisitionMethod).length > 0, "Acquisition method cannot be empty");
        require(bytes(ipfsCID).length > 0, "IPFS CID cannot be empty");
        require(bytes(metadataHash).length > 0, "Metadata hash cannot be empty");
        require(passportToDeed[passportId] == 0, "Passport already has ownership deed");

        _deedIds = _deedIds + 1;
        uint256 deedId = _deedIds;

        OwnershipDeed storage newDeed = ownershipDeeds[deedId];
        newDeed.deedId = deedId;
        newDeed.passportId = passportId;
        newDeed.owner = owner;
        newDeed.acquisitionDate = block.timestamp;
        newDeed.acquisitionPrice = acquisitionPrice;
        newDeed.acquisitionMethod = acquisitionMethod;
        newDeed.ipfsCID = ipfsCID;
        newDeed.metadataHash = metadataHash;
        newDeed.isValid = true;
        newDeed.isLocked = false;
        newDeed.lockExpiry = 0;
        newDeed.previousOwner = address(0);

        // Add additional data
        for (uint256 i = 0; i < additionalData.length; i += 2) {
            if (i + 1 < additionalData.length) {
                string memory key = additionalData[i];
                string memory value = additionalData[i + 1];
                newDeed.additionalData[key] = value;
                newDeed.dataKeys.push(key);
            }
        }

        // Update mappings
        passportToDeed[passportId] = deedId;
        ownerToDeeds[owner].push(deedId);

        // Mint NFT
        _safeMint(owner, deedId);

        emit OwnershipDeedCreated(deedId, passportId, owner, acquisitionPrice, acquisitionMethod, ipfsCID);
    }

    /**
     * @dev Transfer ownership deed
     * @param deedId Ownership deed ID
     * @param to New owner address
     * @param transferPrice Transfer price
     * @param transferType Type of transfer
     * @param ipfsCID IPFS CID containing transfer metadata
     */
    function transferOwnershipDeed(
        uint256 deedId,
        address to,
        uint256 transferPrice,
        TransferType transferType,
        string memory ipfsCID
    ) external validDeed(deedId) onlyDeedOwner(deedId) deedNotLocked(deedId) notEmergencyStopped nonReentrant {
        require(to != address(0), "Invalid recipient address");
        require(to != msg.sender, "Cannot transfer to self");
        require(bytes(ipfsCID).length > 0, "IPFS CID cannot be empty");

        OwnershipDeed storage deed = ownershipDeeds[deedId];
        address from = deed.owner;

        // Handle royalties if applicable
        if (transferPrice > 0 && deedRoyalties[deedId].isActive) {
            uint256 royaltyAmount = (transferPrice * deedRoyalties[deedId].percentage) / FEE_DENOMINATOR;
            if (royaltyAmount > 0) {
                (bool success, ) = payable(deedRoyalties[deedId].recipient).call{value: royaltyAmount}("");
                require(success, "Royalty transfer failed");
                emit RoyaltyPaid(deedId, deedRoyalties[deedId].recipient, royaltyAmount);
            }
        }

        // Update deed
        deed.previousOwner = from;
        deed.owner = to;

        // Update mappings
        _removeDeedFromOwner(from, deedId);
        ownerToDeeds[to].push(deedId);

        // Transfer NFT
        _transfer(from, to, deedId);

        emit OwnershipDeedTransferred(deedId, from, to, transferPrice, transferType);
    }

    /**
     * @dev Lock ownership deed (prevent transfers)
     * @param deedId Ownership deed ID
     * @param lockDuration Duration to lock (in seconds)
     */
    function lockDeed(uint256 deedId, uint256 lockDuration) external validDeed(deedId) onlyDeedOwner(deedId) {
        require(lockDuration > 0, "Lock duration must be greater than 0");
        require(lockDuration <= 365 days, "Lock duration cannot exceed 1 year");

        OwnershipDeed storage deed = ownershipDeeds[deedId];
        deed.isLocked = true;
        deed.lockExpiry = block.timestamp + lockDuration;

        emit DeedLocked(deedId, deed.lockExpiry, msg.sender);
    }

    /**
     * @dev Unlock ownership deed
     * @param deedId Ownership deed ID
     */
    function unlockDeed(uint256 deedId) external validDeed(deedId) onlyDeedOwner(deedId) {
        OwnershipDeed storage deed = ownershipDeeds[deedId];
        require(deed.isLocked, "Deed is not locked");
        require(deed.lockExpiry < block.timestamp, "Lock period not expired");

        deed.isLocked = false;
        deed.lockExpiry = 0;

        emit DeedUnlocked(deedId, msg.sender);
    }

    /**
     * @dev Force unlock deed (only owner or authorized operators)
     * @param deedId Ownership deed ID
     */
    function forceUnlockDeed(uint256 deedId) external onlyAuthorizedOperator validDeed(deedId) {
        OwnershipDeed storage deed = ownershipDeeds[deedId];
        require(deed.isLocked, "Deed is not locked");

        deed.isLocked = false;
        deed.lockExpiry = 0;

        emit DeedUnlocked(deedId, msg.sender);
    }

    // ============ TRANSFER REQUEST MANAGEMENT ============

    /**
     * @dev Create a transfer request
     * @param deedId Ownership deed ID
     * @param to Proposed new owner
     * @param proposedPrice Proposed transfer price
     * @param transferReason Reason for transfer
     */
    function createTransferRequest(
        uint256 deedId,
        address to,
        uint256 proposedPrice,
        string memory transferReason
    ) external validDeed(deedId) deedNotLocked(deedId) notEmergencyStopped {
        require(to != address(0), "Invalid recipient address");
        require(to != msg.sender, "Cannot transfer to self");
        require(bytes(transferReason).length > 0, "Transfer reason cannot be empty");

        // Check if there are too many pending requests
        uint256 pendingCount = 0;
        for (uint256 i = 1; i < _requestIds; i++) {
            TransferRequest storage request = transferRequests[i];
            if (request.deedId == deedId && request.status == TransferStatus.PENDING) {
                pendingCount++;
            }
        }
        require(pendingCount < maxTransferRequests, "Too many pending transfer requests");

        _requestIds = _requestIds + 1;
        uint256 requestId = _requestIds;

        TransferRequest storage newRequest = transferRequests[requestId];
        newRequest.requestId = requestId;
        newRequest.deedId = deedId;
        newRequest.from = ownershipDeeds[deedId].owner;
        newRequest.to = to;
        newRequest.requestDate = block.timestamp;
        newRequest.proposedPrice = proposedPrice;
        newRequest.transferReason = transferReason;
        newRequest.status = TransferStatus.PENDING;
        newRequest.requester = msg.sender;
        newRequest.expiryDate = block.timestamp + transferApprovalPeriod;
        newRequest.isApproved = false;
        newRequest.approver = address(0);

        emit TransferRequestCreated(requestId, deedId, msg.sender, to, proposedPrice, TransferStatus.PENDING);
    }

    /**
     * @dev Approve transfer request
     * @param requestId Transfer request ID
     */
    function approveTransferRequest(uint256 requestId) external validDeed(transferRequests[requestId].deedId) {
        TransferRequest storage request = transferRequests[requestId];
        require(request.requestId != 0, "Transfer request does not exist");
        require(request.status == TransferStatus.PENDING, "Request is not pending");
        require(request.expiryDate > block.timestamp, "Request has expired");
        require(request.from == msg.sender, "Only current owner can approve");

        request.status = TransferStatus.APPROVED;
        request.isApproved = true;
        request.approver = msg.sender;

        emit TransferRequestApproved(requestId, msg.sender);
    }

    /**
     * @dev Reject transfer request
     * @param requestId Transfer request ID
     * @param reason Reason for rejection
     */
    function rejectTransferRequest(uint256 requestId, string memory reason) external validDeed(transferRequests[requestId].deedId) {
        TransferRequest storage request = transferRequests[requestId];
        require(request.requestId != 0, "Transfer request does not exist");
        require(request.status == TransferStatus.PENDING, "Request is not pending");
        require(request.from == msg.sender, "Only current owner can reject");
        require(bytes(reason).length > 0, "Rejection reason cannot be empty");

        request.status = TransferStatus.REJECTED;

        emit TransferRequestRejected(requestId, reason, msg.sender);
    }

    /**
     * @dev Execute approved transfer request
     * @param requestId Transfer request ID
     * @param ipfsCID IPFS CID containing transfer metadata
     */
    function executeTransferRequest(
        uint256 requestId,
        string memory ipfsCID
    ) external validDeed(transferRequests[requestId].deedId) notEmergencyStopped nonReentrant {
        TransferRequest storage request = transferRequests[requestId];
        require(request.requestId != 0, "Transfer request does not exist");
        require(request.status == TransferStatus.APPROVED, "Request is not approved");
        require(request.expiryDate > block.timestamp, "Request has expired");
        require(request.requester == msg.sender, "Only requester can execute");
        require(bytes(ipfsCID).length > 0, "IPFS CID cannot be empty");

        uint256 deedId = request.deedId;
        OwnershipDeed storage deed = ownershipDeeds[deedId];

        // Handle royalties if applicable
        if (request.proposedPrice > 0 && deedRoyalties[deedId].isActive) {
            uint256 royaltyAmount = (request.proposedPrice * deedRoyalties[deedId].percentage) / FEE_DENOMINATOR;
            if (royaltyAmount > 0) {
                (bool success, ) = payable(deedRoyalties[deedId].recipient).call{value: royaltyAmount}("");
                require(success, "Royalty transfer failed");
                emit RoyaltyPaid(deedId, deedRoyalties[deedId].recipient, royaltyAmount);
            }
        }

        // Update deed
        deed.previousOwner = request.from;
        deed.owner = request.to;

        // Update mappings
        _removeDeedFromOwner(request.from, deedId);
        ownerToDeeds[request.to].push(deedId);

        // Transfer NFT
        _transfer(request.from, request.to, deedId);

        // Mark request as completed
        request.status = TransferStatus.APPROVED;

        emit OwnershipDeedTransferred(deedId, request.from, request.to, request.proposedPrice, TransferType.SECONDARY_SALE);
    }

    // ============ ROYALTY MANAGEMENT ============

    /**
     * @dev Set royalty for a deed
     * @param deedId Ownership deed ID
     * @param recipient Royalty recipient
     * @param percentage Royalty percentage in basis points
     */
    function setRoyalty(
        uint256 deedId,
        address recipient,
        uint256 percentage
    ) external validDeed(deedId) onlyDeedOwner(deedId) {
        require(recipient != address(0), "Invalid recipient address");
        require(percentage <= 1000, "Royalty percentage cannot exceed 10%");

        RoyaltyInfo storage royalty = deedRoyalties[deedId];
        royalty.recipient = recipient;
        royalty.percentage = percentage;
        royalty.isActive = true;

        emit RoyaltySet(deedId, recipient, percentage);
    }

    /**
     * @dev Disable royalty for a deed
     * @param deedId Ownership deed ID
     */
    function disableRoyalty(uint256 deedId) external validDeed(deedId) onlyDeedOwner(deedId) {
        deedRoyalties[deedId].isActive = false;
    }

    // ============ ADMIN FUNCTIONS ============

    /**
     * @dev Authorize a brand
     * @param brand Address to authorize
     */
    function authorizeBrand(address brand) external onlyOwner {
        require(brand != address(0), "Invalid address");
        authorizedBrands[brand] = true;
    }

    /**
     * @dev Authorize an operator
     * @param operator Address to authorize
     */
    function authorizeOperator(address operator) external onlyOwner {
        require(operator != address(0), "Invalid address");
        authorizedOperators[operator] = true;
    }

    /**
     * @dev Authorize a transfer agent
     * @param transferAgent Address to authorize
     */
    function authorizeTransferAgent(address transferAgent) external onlyOwner {
        require(transferAgent != address(0), "Invalid address");
        authorizedTransferAgents[transferAgent] = true;
    }

    /**
     * @dev Revoke authorizations
     * @param target Address to revoke
     */
    function revokeAuthorization(address target) external onlyOwner {
        authorizedBrands[target] = false;
        authorizedOperators[target] = false;
        authorizedTransferAgents[target] = false;
    }

    /**
     * @dev Set fees and settings
     * @param newTransferFee New transfer fee
     * @param newRoyaltyFee New royalty fee
     * @param newApprovalPeriod New approval period
     * @param newMaxRequests New max transfer requests
     */
    function setSettings(
        uint256 newTransferFee,
        uint256 newRoyaltyFee,
        uint256 newApprovalPeriod,
        uint256 newMaxRequests
    ) external onlyOwner {
        transferFee = newTransferFee;
        royaltyFee = newRoyaltyFee;
        transferApprovalPeriod = newApprovalPeriod;
        maxTransferRequests = newMaxRequests;
    }

    /**
     * @dev Activate emergency stop
     */
    function activateEmergencyStop() external onlyOwner {
        emergencyStop = true;
    }

    /**
     * @dev Deactivate emergency stop
     */
    function deactivateEmergencyStop() external onlyOwner {
        emergencyStop = false;
    }

    /**
     * @dev Pause contract
     */
    function pause() external onlyOwner {
        _pause();
    }

    /**
     * @dev Unpause contract
     */
    function unpause() external onlyOwner {
        _unpause();
    }

    /**
     * @dev Withdraw fees
     */
    function withdrawFees() external onlyOwner {
        uint256 balance = address(this).balance;
        require(balance > 0, "No fees to withdraw");

        (bool success, ) = payable(owner()).call{value: balance}("");
        require(success, "Transfer failed");
    }

    // ============ VIEW FUNCTIONS ============

    /**
     * @dev Get ownership deed details
     * @param deedId Ownership deed ID
     */
    function getOwnershipDeedDetails(uint256 deedId) external view returns (
        uint256 passportId,
        address owner,
        uint256 acquisitionDate,
        uint256 acquisitionPrice,
        string memory acquisitionMethod,
        string memory ipfsCID,
        string memory metadataHash,
        bool isValid,
        bool isLocked,
        uint256 lockExpiry,
        address previousOwner
    ) {
        OwnershipDeed storage deed = ownershipDeeds[deedId];
        return (
            deed.passportId,
            deed.owner,
            deed.acquisitionDate,
            deed.acquisitionPrice,
            deed.acquisitionMethod,
            deed.ipfsCID,
            deed.metadataHash,
            deed.isValid,
            deed.isLocked,
            deed.lockExpiry,
            deed.previousOwner
        );
    }

    /**
     * @dev Get deed by passport ID
     * @param passportId Product passport ID
     */
    function getDeedByPassportId(uint256 passportId) external view returns (uint256) {
        return passportToDeed[passportId];
    }

    /**
     * @dev Get all deeds owned by an address
     * @param owner Owner address
     */
    function getDeedsByOwner(address owner) external view returns (uint256[] memory) {
        return ownerToDeeds[owner];
    }

    /**
     * @dev Get transfer request details
     * @param requestId Transfer request ID
     */
    function getTransferRequestDetails(uint256 requestId) external view returns (
        uint256 deedId,
        address from,
        address to,
        uint256 requestDate,
        uint256 proposedPrice,
        string memory transferReason,
        TransferStatus status,
        address requester,
        uint256 expiryDate,
        bool isApproved,
        address approver
    ) {
        TransferRequest storage request = transferRequests[requestId];
        return (
            request.deedId,
            request.from,
            request.to,
            request.requestDate,
            request.proposedPrice,
            request.transferReason,
            request.status,
            request.requester,
            request.expiryDate,
            request.isApproved,
            request.approver
        );
    }

    /**
     * @dev Get royalty information for a deed
     * @param deedId Ownership deed ID
     */
    function getRoyaltyInfo(uint256 deedId) external view returns (
        address recipient,
        uint256 percentage,
        bool isActive
    ) {
        RoyaltyInfo storage royalty = deedRoyalties[deedId];
        return (
            royalty.recipient,
            royalty.percentage,
            royalty.isActive
        );
    }

    /**
     * @dev Get additional data for a deed
     * @param deedId Ownership deed ID
     * @param key Data key
     */
    function getDeedData(uint256 deedId, string memory key) external view returns (string memory) {
        return ownershipDeeds[deedId].additionalData[key];
    }

    /**
     * @dev Get all data keys for a deed
     * @param deedId Ownership deed ID
     */
    function getDeedDataKeys(uint256 deedId) external view returns (string[] memory) {
        return ownershipDeeds[deedId].dataKeys;
    }

    /**
     * @dev Get pending transfer requests for a deed
     * @param deedId Ownership deed ID
     */
    function getPendingTransferRequests(uint256 deedId) external view returns (uint256[] memory) {
        uint256[] memory pendingRequests = new uint256[](_requestIds);
        uint256 count = 0;

        for (uint256 i = 1; i < _requestIds; i++) {
            TransferRequest storage request = transferRequests[i];
            if (request.deedId == deedId && request.status == TransferStatus.PENDING) {
                pendingRequests[count] = i;
                count++;
            }
        }

        // Resize array to actual count
        uint256[] memory result = new uint256[](count);
        for (uint256 i = 0; i < count; i++) {
            result[i] = pendingRequests[i];
        }

        return result;
    }

    /**
     * @dev Get total number of deeds
     */
    function getTotalDeeds() external view returns (uint256) {
        return _deedIds - 1;
    }

    /**
     * @dev Get total number of transfer requests
     */
    function getTotalTransferRequests() external view returns (uint256) {
        return _requestIds - 1;
    }

    // ============ INTERNAL FUNCTIONS ============

    /**
     * @dev Remove deed from owner's list
     * @param owner Owner address
     * @param deedId Deed ID to remove
     */
    function _removeDeedFromOwner(address owner, uint256 deedId) internal {
        uint256[] storage deeds = ownerToDeeds[owner];
        for (uint256 i = 0; i < deeds.length; i++) {
            if (deeds[i] == deedId) {
                deeds[i] = deeds[deeds.length - 1];
                deeds.pop();
                break;
            }
        }
    }



    // ============ RECEIVE FUNCTION ============

    receive() external payable {
        // Contract can receive ETH for fees and royalties
    }
}

contracts/TrataTechOwnershipRegistryUpgr.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts-upgradeable/token/ERC721/ERC721Upgradeable.sol";
import "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/PausableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/ReentrancyGuardUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/metatx/ERC2771ContextUpgradeable.sol";

import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import "@openzeppelin/contracts/utils/Strings.sol";

/**
 * @title TrataTechOwnershipRegistryUpgradeable
 * @dev Upgradeable and gasless version of Ownership Registry Contract for managing NFT-linked digital deeds and transfer logic
 * @author Advanced Developer
 */
contract TrataTechOwnershipRegistryUpgradeable is 
    Initializable,
    ERC721Upgradeable,
    OwnableUpgradeable,
    PausableUpgradeable,
    ReentrancyGuardUpgradeable,
    UUPSUpgradeable,
    ERC2771ContextUpgradeable
{
    using ECDSA for bytes32;
    using Strings for uint256;

    // ============ STRUCTS ============

    struct OwnershipDeed {
        uint256 deedId;
        uint256 passportId;
        address owner;
        uint256 acquisitionDate;
        uint256 acquisitionPrice;
        string acquisitionMethod;
        string ipfsCID;
        string metadataHash;
        bool isValid;
        bool isLocked;
        uint256 lockExpiry;
        address previousOwner;
        uint256 pendingRequestCount; // Track count to avoid loop
        mapping(string => string) additionalData;
        string[] dataKeys;
    }

    struct TransferRequest {
        uint256 requestId;
        uint256 deedId;
        address from;
        address to;
        uint256 requestDate;
        uint256 proposedPrice;
        string transferReason;
        TransferStatus status;
        address requester;
        uint256 expiryDate;
        bool isApproved;
        address approver;
    }

    struct RoyaltyInfo {
        address recipient;
        uint256 percentage; // In basis points (e.g., 500 = 5%)
        bool isActive;
    }

    enum TransferStatus {
        PENDING,
        APPROVED,
        REJECTED,
        EXPIRED,
        CANCELLED
    }

    enum TransferType {
        PRIMARY_SALE,
        SECONDARY_SALE,
        GIFT,
        INHERITANCE,
        LOAN,
        CONSIGNMENT,
        AUCTION,
        CUSTOM
    }

    // ============ STATE VARIABLES ============

    uint256 private _deedIds;
    uint256 private _requestIds;

    // Mappings
    mapping(uint256 => OwnershipDeed) public ownershipDeeds;
    mapping(uint256 => TransferRequest) public transferRequests;
    mapping(uint256 => uint256) public passportToDeed;
    mapping(address => uint256[]) public ownerToDeeds;
    mapping(uint256 => RoyaltyInfo) public deedRoyalties;
    mapping(address => bool) public authorizedBrands;
    mapping(address => bool) public authorizedOperators;
    mapping(address => bool) public authorizedTransferAgents;

    // Reserved for future use
    uint256[50] private __gap;
    uint256 public constant FEE_DENOMINATOR = 10000;

    // Transfer settings
    uint256 public transferApprovalPeriod;
    uint256 public maxTransferRequests;

    // Emergency controls
    bool public emergencyStop;

    // Duplicate gap removed

    // ============ EVENTS ============

    event OwnershipDeedCreated(
        uint256 indexed deedId,
        uint256 indexed passportId,
        address indexed owner,
        uint256 acquisitionPrice,
        string acquisitionMethod,
        string ipfsCID
    );

    event OwnershipDeedTransferred(
        uint256 indexed deedId,
        address indexed from,
        address indexed to,
        uint256 transferPrice,
        TransferType transferType
    );

    event TransferRequestCreated(
        uint256 indexed requestId,
        uint256 indexed deedId,
        address indexed from,
        address to,
        uint256 proposedPrice,
        TransferStatus status
    );

    event TransferRequestApproved(
        uint256 indexed requestId,
        address indexed approver
    );

    event TransferRequestRejected(
        uint256 indexed requestId,
        string reason,
        address indexed rejector
    );

    event DeedLocked(
        uint256 indexed deedId,
        uint256 lockExpiry,
        address indexed locker
    );

    event DeedUnlocked(
        uint256 indexed deedId,
        address indexed unlocker
    );

    event RoyaltySet(
        uint256 indexed deedId,
        address indexed recipient,
        uint256 percentage
    );

    event RoyaltyPaid(
        uint256 indexed deedId,
        address indexed recipient,
        uint256 amount
    );

    // ============ MODIFIERS ============

    modifier onlyAuthorizedBrand() {
        require(authorizedBrands[_msgSender()] || _msgSender() == owner(), "Not authorized brand");
        _;
    }

    modifier onlyAuthorizedOperator() {
        require(authorizedOperators[_msgSender()] || _msgSender() == owner(), "Not authorized operator");
        _;
    }

    modifier onlyAuthorizedTransferAgent() {
        require(authorizedTransferAgents[_msgSender()] || _msgSender() == owner(), "Not authorized transfer agent");
        _;
    }

    modifier notEmergencyStopped() {
        require(!emergencyStop, "Contract is emergency stopped");
        _;
    }

    modifier validDeed(uint256 deedId) {
        require(ownershipDeeds[deedId].deedId != 0, "Ownership deed does not exist");
        require(ownershipDeeds[deedId].isValid, "Ownership deed is invalid");
        _;
    }

    modifier onlyDeedOwner(uint256 deedId) {
        require(ownershipDeeds[deedId].owner == _msgSender(), "Not deed owner");
        _;
    }

    modifier deedNotLocked(uint256 deedId) {
        require(!ownershipDeeds[deedId].isLocked || ownershipDeeds[deedId].lockExpiry < block.timestamp, "Deed is locked");
        _;
    }

    // ============ INITIALIZATION ============

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor(address trustedForwarder) ERC2771ContextUpgradeable(trustedForwarder) {
        require(trustedForwarder != address(0), "TrataTech: Invalid trusted forwarder");
        _disableInitializers();
    }

    function initialize(address initialOwner, address trustedForwarder) public initializer {
        __ERC721_init("TrataTech Ownership Deed", "TRATA-DEED");
        __Ownable_init(initialOwner);
        __Pausable_init();
        __ReentrancyGuard_init();
        __UUPSUpgradeable_init();
        // ERC2771Context initialization removed - constructor handles this

        _deedIds = 1; // Start from 1
        _requestIds = 1; // Start from 1
        // Fee collection removed - no blockchain payments
        transferApprovalPeriod = 7 days;
        maxTransferRequests = 5;
    }

    // ============ UUPS UPGRADE AUTHORIZATION ============

    function _authorizeUpgrade(address newImplementation) internal override onlyOwner {}

    // ============ ERC2771 OVERRIDES FOR GASLESS ============

    function _msgSender() internal view virtual override(ContextUpgradeable, ERC2771ContextUpgradeable) returns (address) {
        return ERC2771ContextUpgradeable._msgSender();
    }

    function _msgData() internal view virtual override(ContextUpgradeable, ERC2771ContextUpgradeable) returns (bytes calldata) {
        return ERC2771ContextUpgradeable._msgData();
    }

    function _contextSuffixLength() internal view virtual override(ContextUpgradeable, ERC2771ContextUpgradeable) returns (uint256) {
        return ERC2771ContextUpgradeable._contextSuffixLength();
    }

    // ============ OWNERSHIP DEED MANAGEMENT ============

    function createOwnershipDeed(
        uint256 passportId,
        address owner,
        uint256 acquisitionPrice,
        string memory acquisitionMethod,
        string memory ipfsCID,
        string memory metadataHash,
        string[] memory additionalData
    ) external onlyAuthorizedBrand notEmergencyStopped nonReentrant {
        require(passportId > 0, "Invalid passport ID");
        require(owner != address(0), "Invalid owner address");
        require(bytes(acquisitionMethod).length > 0, "Acquisition method cannot be empty");
        require(bytes(ipfsCID).length > 0, "IPFS CID cannot be empty");
        require(bytes(metadataHash).length > 0, "Metadata hash cannot be empty");
        require(passportToDeed[passportId] == 0, "Passport already has ownership deed");

        _deedIds = _deedIds + 1;
        uint256 deedId = _deedIds;

        OwnershipDeed storage newDeed = ownershipDeeds[deedId];
        newDeed.deedId = deedId;
        newDeed.passportId = passportId;
        newDeed.owner = owner;
        newDeed.acquisitionDate = block.timestamp;
        newDeed.acquisitionPrice = acquisitionPrice;
        newDeed.acquisitionMethod = acquisitionMethod;
        newDeed.ipfsCID = ipfsCID;
        newDeed.metadataHash = metadataHash;
        newDeed.isValid = true;
        newDeed.isLocked = false;
        newDeed.pendingRequestCount = 0;
        newDeed.lockExpiry = 0;
        newDeed.previousOwner = address(0);

        // Add additional data
        for (uint256 i = 0; i < additionalData.length; i += 2) {
            if (i + 1 < additionalData.length) {
                string memory key = additionalData[i];
                string memory value = additionalData[i + 1];
                newDeed.additionalData[key] = value;
                newDeed.dataKeys.push(key);
            }
        }

        // Update mappings
        passportToDeed[passportId] = deedId;
        ownerToDeeds[owner].push(deedId);

        // Mint NFT
        _safeMint(owner, deedId);

        emit OwnershipDeedCreated(deedId, passportId, owner, acquisitionPrice, acquisitionMethod, ipfsCID);
    }

    function transferOwnershipDeed(
        uint256 deedId,
        address to,
        uint256 transferPrice,
        TransferType transferType,
        string memory ipfsCID
    ) external validDeed(deedId) onlyDeedOwner(deedId) deedNotLocked(deedId) notEmergencyStopped nonReentrant {
        require(to != address(0), "Invalid recipient address");
        require(to != _msgSender(), "Cannot transfer to self");
        require(bytes(ipfsCID).length > 0, "IPFS CID cannot be empty");

        OwnershipDeed storage deed = ownershipDeeds[deedId];
        address from = deed.owner;

        // Handle royalties if applicable
        if (transferPrice > 0 && deedRoyalties[deedId].isActive) {
            uint256 royaltyAmount = (transferPrice * deedRoyalties[deedId].percentage) / FEE_DENOMINATOR;
            if (royaltyAmount > 0) {
                // Royalty payment removed - no blockchain payments
                emit RoyaltyPaid(deedId, deedRoyalties[deedId].recipient, royaltyAmount);
            }
        }

        // Update deed
        deed.previousOwner = from;
        deed.owner = to;

        // Update mappings
        _removeDeedFromOwner(from, deedId);
        ownerToDeeds[to].push(deedId);

        // Transfer NFT
        _transfer(from, to, deedId);

        emit OwnershipDeedTransferred(deedId, from, to, transferPrice, transferType);
    }

    function lockDeed(uint256 deedId, uint256 lockDuration) external validDeed(deedId) onlyDeedOwner(deedId) {
        require(lockDuration > 0, "Lock duration must be greater than 0");
        require(lockDuration <= 365 days, "Lock duration cannot exceed 1 year");

        OwnershipDeed storage deed = ownershipDeeds[deedId];
        deed.isLocked = true;
        deed.lockExpiry = block.timestamp + lockDuration;

        emit DeedLocked(deedId, deed.lockExpiry, _msgSender());
    }

    function unlockDeed(uint256 deedId) external validDeed(deedId) onlyDeedOwner(deedId) {
        OwnershipDeed storage deed = ownershipDeeds[deedId];
        require(deed.isLocked, "Deed is not locked");
        require(deed.lockExpiry < block.timestamp, "Lock period not expired");

        deed.isLocked = false;
        deed.lockExpiry = 0;

        emit DeedUnlocked(deedId, _msgSender());
    }

    function forceUnlockDeed(uint256 deedId) external onlyAuthorizedOperator validDeed(deedId) {
        OwnershipDeed storage deed = ownershipDeeds[deedId];
        require(deed.isLocked, "Deed is not locked");

        deed.isLocked = false;
        deed.lockExpiry = 0;

        emit DeedUnlocked(deedId, _msgSender());
    }

    // ============ TRANSFER REQUEST MANAGEMENT ============

    function createTransferRequest(
        uint256 deedId,
        address to,
        uint256 proposedPrice,
        string memory transferReason
    ) external validDeed(deedId) deedNotLocked(deedId) notEmergencyStopped {
        require(to != address(0), "Invalid recipient address");
        require(to != _msgSender(), "Cannot transfer to self");
        require(bytes(transferReason).length > 0, "Transfer reason cannot be empty");

        // Check if there are too many pending requests using counter
        OwnershipDeed storage deed = ownershipDeeds[deedId];
        require(deed.pendingRequestCount < maxTransferRequests, "Too many pending transfer requests");

        _requestIds = _requestIds + 1;
        uint256 requestId = _requestIds;

        TransferRequest storage newRequest = transferRequests[requestId];
        newRequest.requestId = requestId;
        newRequest.deedId = deedId;
        newRequest.from = ownershipDeeds[deedId].owner;
        newRequest.to = to;
        newRequest.requestDate = block.timestamp;
        newRequest.proposedPrice = proposedPrice;
        newRequest.transferReason = transferReason;
        newRequest.status = TransferStatus.PENDING;
        newRequest.requester = _msgSender();
        newRequest.expiryDate = block.timestamp + transferApprovalPeriod;
        newRequest.isApproved = false;
        newRequest.approver = address(0);

        // Increment pending request counter
        deed.pendingRequestCount++;

        emit TransferRequestCreated(requestId, deedId, _msgSender(), to, proposedPrice, TransferStatus.PENDING);
    }

    function approveTransferRequest(uint256 requestId) external validDeed(transferRequests[requestId].deedId) {
        TransferRequest storage request = transferRequests[requestId];
        require(request.requestId != 0, "Transfer request does not exist");
        require(request.status == TransferStatus.PENDING, "Request is not pending");
        require(request.expiryDate > block.timestamp, "Request has expired");
        require(request.from == _msgSender(), "Only current owner can approve");

        request.status = TransferStatus.APPROVED;
        request.isApproved = true;
        request.approver = _msgSender();

        // Decrement pending request counter
        OwnershipDeed storage deed = ownershipDeeds[request.deedId];
        deed.pendingRequestCount--;

        emit TransferRequestApproved(requestId, _msgSender());
    }

    function rejectTransferRequest(uint256 requestId, string memory reason) external validDeed(transferRequests[requestId].deedId) {
        TransferRequest storage request = transferRequests[requestId];
        require(request.requestId != 0, "Transfer request does not exist");
        require(request.status == TransferStatus.PENDING, "Request is not pending");
        require(request.from == _msgSender(), "Only current owner can reject");
        require(bytes(reason).length > 0, "Rejection reason cannot be empty");

        request.status = TransferStatus.REJECTED;

        // Decrement pending request counter
        OwnershipDeed storage deed = ownershipDeeds[request.deedId];
        deed.pendingRequestCount--;

        emit TransferRequestRejected(requestId, reason, _msgSender());
    }

    function executeTransferRequest(
        uint256 requestId,
        string memory ipfsCID
    ) external validDeed(transferRequests[requestId].deedId) notEmergencyStopped nonReentrant {
        TransferRequest storage request = transferRequests[requestId];
        require(request.requestId != 0, "Transfer request does not exist");
        require(request.status == TransferStatus.APPROVED, "Request is not approved");
        require(request.expiryDate > block.timestamp, "Request has expired");
        require(request.requester == _msgSender(), "Only requester can execute");
        require(bytes(ipfsCID).length > 0, "IPFS CID cannot be empty");

        uint256 deedId = request.deedId;
        OwnershipDeed storage deed = ownershipDeeds[deedId];

        // Handle royalties if applicable
        if (request.proposedPrice > 0 && deedRoyalties[deedId].isActive) {
            uint256 royaltyAmount = (request.proposedPrice * deedRoyalties[deedId].percentage) / FEE_DENOMINATOR;
            if (royaltyAmount > 0) {
                // Royalty payment removed - no blockchain payments
                emit RoyaltyPaid(deedId, deedRoyalties[deedId].recipient, royaltyAmount);
            }
        }

        // Update deed
        deed.previousOwner = request.from;
        deed.owner = request.to;

        // Update mappings
        _removeDeedFromOwner(request.from, deedId);
        ownerToDeeds[request.to].push(deedId);

        // Transfer NFT
        _transfer(request.from, request.to, deedId);

        // Mark request as completed
        request.status = TransferStatus.APPROVED;

        emit OwnershipDeedTransferred(deedId, request.from, request.to, request.proposedPrice, TransferType.SECONDARY_SALE);
    }

    // ============ ROYALTY MANAGEMENT ============

    function setRoyalty(
        uint256 deedId,
        address recipient,
        uint256 percentage
    ) external validDeed(deedId) onlyDeedOwner(deedId) {
        require(recipient != address(0), "Invalid recipient address");
        require(percentage <= 1000, "Royalty percentage cannot exceed 10%");

        RoyaltyInfo storage royalty = deedRoyalties[deedId];
        royalty.recipient = recipient;
        royalty.percentage = percentage;
        royalty.isActive = true;

        emit RoyaltySet(deedId, recipient, percentage);
    }

    function disableRoyalty(uint256 deedId) external validDeed(deedId) onlyDeedOwner(deedId) {
        deedRoyalties[deedId].isActive = false;
    }

    // ============ ADMIN FUNCTIONS ============

    function authorizeBrand(address brand) external onlyOwner {
        require(brand != address(0), "Invalid address");
        authorizedBrands[brand] = true;
    }

    function authorizeOperator(address operator) external onlyOwner {
        require(operator != address(0), "Invalid address");
        authorizedOperators[operator] = true;
    }

    function authorizeTransferAgent(address transferAgent) external onlyOwner {
        require(transferAgent != address(0), "Invalid address");
        authorizedTransferAgents[transferAgent] = true;
    }

    function revokeAuthorization(address target) external onlyOwner {
        authorizedBrands[target] = false;
        authorizedOperators[target] = false;
        authorizedTransferAgents[target] = false;
    }

    function setSettings(
        uint256 newApprovalPeriod,
        uint256 newMaxRequests
    ) external onlyOwner {
        transferApprovalPeriod = newApprovalPeriod;
        maxTransferRequests = newMaxRequests;
    }

    function activateEmergencyStop() external onlyOwner {
        emergencyStop = true;
    }

    function deactivateEmergencyStop() external onlyOwner {
        emergencyStop = false;
    }

    function pause() external onlyOwner {
        _pause();
    }

    function unpause() external onlyOwner {
        _unpause();
    }

    // Fee withdrawal removed - no blockchain payments

    // ============ VIEW FUNCTIONS ============

    function getOwnershipDeedDetails(uint256 deedId) external view returns (
        uint256 passportId,
        address owner,
        uint256 acquisitionDate,
        uint256 acquisitionPrice,
        string memory acquisitionMethod,
        string memory ipfsCID,
        string memory metadataHash,
        bool isValid,
        bool isLocked,
        uint256 lockExpiry,
        address previousOwner
    ) {
        OwnershipDeed storage deed = ownershipDeeds[deedId];
        return (
            deed.passportId,
            deed.owner,
            deed.acquisitionDate,
            deed.acquisitionPrice,
            deed.acquisitionMethod,
            deed.ipfsCID,
            deed.metadataHash,
            deed.isValid,
            deed.isLocked,
            deed.lockExpiry,
            deed.previousOwner
        );
    }

    function getDeedByPassportId(uint256 passportId) external view returns (uint256) {
        return passportToDeed[passportId];
    }

    function getDeedsByOwner(address owner) external view returns (uint256[] memory) {
        return ownerToDeeds[owner];
    }

    function getTransferRequestDetails(uint256 requestId) external view returns (
        uint256 deedId,
        address from,
        address to,
        uint256 requestDate,
        uint256 proposedPrice,
        string memory transferReason,
        TransferStatus status,
        address requester,
        uint256 expiryDate,
        bool isApproved,
        address approver
    ) {
        TransferRequest storage request = transferRequests[requestId];
        return (
            request.deedId,
            request.from,
            request.to,
            request.requestDate,
            request.proposedPrice,
            request.transferReason,
            request.status,
            request.requester,
            request.expiryDate,
            request.isApproved,
            request.approver
        );
    }

    function getRoyaltyInfo(uint256 deedId) external view returns (
        address recipient,
        uint256 percentage,
        bool isActive
    ) {
        RoyaltyInfo storage royalty = deedRoyalties[deedId];
        return (
            royalty.recipient,
            royalty.percentage,
            royalty.isActive
        );
    }

    function getDeedData(uint256 deedId, string memory key) external view returns (string memory) {
        return ownershipDeeds[deedId].additionalData[key];
    }

    function getDeedDataKeys(uint256 deedId) external view returns (string[] memory) {
        return ownershipDeeds[deedId].dataKeys;
    }

    function getPendingTransferRequests(uint256 deedId) external view returns (uint256[] memory) {
        uint256[] memory pendingRequests = new uint256[](_requestIds);
        uint256 count = 0;

        for (uint256 i = 1; i < _requestIds; i++) {
            TransferRequest storage request = transferRequests[i];
            if (request.deedId == deedId && request.status == TransferStatus.PENDING) {
                pendingRequests[count] = i;
                count++;
            }
        }

        // Resize array to actual count
        uint256[] memory result = new uint256[](count);
        for (uint256 i = 0; i < count; i++) {
            result[i] = pendingRequests[i];
        }

        return result;
    }

    function getTotalDeeds() external view returns (uint256) {
        return _deedIds - 1;
    }

    function getTotalTransferRequests() external view returns (uint256) {
        return _requestIds - 1;
    }

    // ============ INTERNAL FUNCTIONS ============

    function _removeDeedFromOwner(address owner, uint256 deedId) internal {
        uint256[] storage deeds = ownerToDeeds[owner];
        for (uint256 i = 0; i < deeds.length; i++) {
            if (deeds[i] == deedId) {
                deeds[i] = deeds[deeds.length - 1];
                deeds.pop();
                break;
            }
        }
    }

    // ============ VERSION FUNCTION ============

    function version() external pure returns (string memory) {
        return "1.0.0";
    }

    // ============ RECEIVE FUNCTION ============

    // Receive function removed - no blockchain payments
}

contracts/TrataTechProductPassport.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import "@openzeppelin/contracts/utils/Strings.sol";


/**
 * @title TrataTechProductPassport
 * @dev Product Passport Contract for recording item-specific data including serial numbers, 
 * materials, and date/location of manufacture with IPFS integration
 * @author Advanced Developer
 */
contract TrataTechProductPassport is Ownable, Pausable, ReentrancyGuard {

    using ECDSA for bytes32;
    using Strings for uint256;


    // ============ STRUCTS ============

    struct ProductPassport {
        uint256 passportId;
        string serialNumber;
        string brandId;
        string productName;
        string productDescription;
        string materials;
        string manufacturingLocation;
        uint256 manufacturingDate;
        uint256 creationTimestamp;
        string ipfsCID;
        string metadataHash;
        bool isValid;
        bool isRecalled;
        address creator;
        address brandAddress;
        mapping(string => string) additionalAttributes;
        string[] attributeKeys;
    }

    struct Brand {
        string brandId;
        string brandName;
        string brandDescription;
        string ipfsCID;
        bool isActive;
        bool isVerified;
        address brandAddress;
        uint256 registrationDate;
        string[] authorizedCountries;
        mapping(string => bool) countryAuthorizations;
    }

    struct ManufacturingCertificate {
        uint256 certificateId;
        uint256 passportId;
        string certificateType;
        string certificateNumber;
        string issuingAuthority;
        uint256 issueDate;
        uint256 expiryDate;
        string ipfsCID;
        bool isValid;
        address issuer;
    }

    // ============ STATE VARIABLES ============

    uint256 private _passportIds = 0;
    uint256 private _certificateIds = 0;

    // Mappings
    mapping(uint256 => ProductPassport) private _productPassports;
    mapping(string => Brand) private _brands;
    mapping(uint256 => ManufacturingCertificate) private _certificates;
    mapping(string => uint256) private _serialNumberToPassportId;
    mapping(address => bool) private _authorizedBrands;
    mapping(address => bool) private _authorizedManufacturers;
    mapping(address => bool) private _authorizedCertifiers;
    mapping(address => bool) private _authorizedOperators;

    // Brand management
    mapping(string => address) private _brandIdToAddress;
    mapping(address => string) private _addressToBrandId;

    // Fee structure
    uint256 private _passportCreationFee = 0.01 ether;
    uint256 private _certificateCreationFee = 0.005 ether;
    uint256 public constant FEE_DENOMINATOR = 10000;

    // Emergency controls
    bool private _emergencyStop = false;

    // ============ EVENTS ============

    event ProductPassportCreated(
        uint256 indexed passportId,
        string serialNumber,
        string brandId,
        string productName,
        string ipfsCID,
        address indexed creator
    );

    event ProductPassportUpdated(
        uint256 indexed passportId,
        string ipfsCID,
        string metadataHash
    );

    event ProductPassportInvalidated(
        uint256 indexed passportId,
        string reason
    );

    event BrandRegistered(
        string indexed brandId,
        string brandName,
        address indexed brandAddress,
        string ipfsCID
    );

    event BrandVerified(string indexed brandId);

    event ManufacturingCertificateCreated(
        uint256 indexed certificateId,
        uint256 indexed passportId,
        string certificateType,
        string certificateNumber,
        string ipfsCID,
        address indexed issuer
    );

    event CertificateInvalidated(uint256 indexed certificateId);

    event BrandAuthorized(address indexed brand);
    event BrandRevoked(address indexed brand);
    event ManufacturerAuthorized(address indexed manufacturer);
    event ManufacturerRevoked(address indexed manufacturer);
    event CertifierAuthorized(address indexed certifier);
    event CertifierRevoked(address indexed certifier);
    event OperatorAuthorized(address indexed operator);
    event OperatorRevoked(address indexed operator);

    event EmergencyStopActivated();
    event EmergencyStopDeactivated();

    // ============ MODIFIERS ============

    modifier onlyAuthorizedBrand() {
        require(_authorizedBrands[msg.sender] || msg.sender == owner(), "Not authorized brand");
        _;
    }

    modifier onlyAuthorizedManufacturer() {
        require(_authorizedManufacturers[msg.sender] || msg.sender == owner(), "Not authorized manufacturer");
        _;
    }

    modifier onlyAuthorizedCertifier() {
        require(_authorizedCertifiers[msg.sender] || msg.sender == owner(), "Not authorized certifier");
        _;
    }

    modifier onlyAuthorizedOperator() {
        require(_authorizedOperators[msg.sender] || msg.sender == owner(), "Not authorized operator");
        _;
    }

    modifier notEmergencyStopped() {
        require(!_emergencyStop, "Contract is emergency stopped");
        _;
    }

    modifier validPassport(uint256 passportId) {
        require(_productPassports[passportId].passportId != 0, "Passport does not exist");
        require(_productPassports[passportId].isValid, "Passport is invalid");
        require(!_productPassports[passportId].isRecalled, "Passport is recalled");
        _;
    }

    modifier validBrand(string memory brandId) {
        require(bytes(_brands[brandId].brandId).length > 0, "Brand does not exist");
        require(_brands[brandId].isActive, "Brand is not active");
        _;
    }

    // ============ CONSTRUCTOR ============

    constructor() Ownable(msg.sender) {
        // Initialize with default values
    }

    // ============ GETTER FUNCTIONS ============

    function productPassports(uint256 passportId) external view returns (
        uint256 passportId_,
        string memory serialNumber,
        string memory brandId,
        string memory productName,
        string memory productDescription,
        string memory materials,
        string memory manufacturingLocation,
        uint256 manufacturingDate,
        uint256 creationTimestamp,
        string memory ipfsCID,
        string memory metadataHash,
        bool isValid,
        bool isRecalled,
        address creator,
        address brandAddress
    ) {
        ProductPassport storage passport = _productPassports[passportId];
        return (
            passport.passportId,
            passport.serialNumber,
            passport.brandId,
            passport.productName,
            passport.productDescription,
            passport.materials,
            passport.manufacturingLocation,
            passport.manufacturingDate,
            passport.creationTimestamp,
            passport.ipfsCID,
            passport.metadataHash,
            passport.isValid,
            passport.isRecalled,
            passport.creator,
            passport.brandAddress
        );
    }

    function brands(string memory brandId) external view returns (
        string memory brandId_,
        string memory brandName,
        string memory brandDescription,
        string memory ipfsCID,
        bool isActive,
        bool isVerified,
        address brandAddress,
        uint256 registrationDate
    ) {
        Brand storage brand = _brands[brandId];
        return (
            brand.brandId,
            brand.brandName,
            brand.brandDescription,
            brand.ipfsCID,
            brand.isActive,
            brand.isVerified,
            brand.brandAddress,
            brand.registrationDate
        );
    }

    function certificates(uint256 certificateId) external view returns (
        uint256 certificateId_,
        uint256 passportId,
        string memory certificateType,
        string memory certificateNumber,
        string memory issuingAuthority,
        uint256 issueDate,
        uint256 expiryDate,
        string memory ipfsCID,
        bool isValid,
        address issuer
    ) {
        ManufacturingCertificate storage cert = _certificates[certificateId];
        return (
            cert.certificateId,
            cert.passportId,
            cert.certificateType,
            cert.certificateNumber,
            cert.issuingAuthority,
            cert.issueDate,
            cert.expiryDate,
            cert.ipfsCID,
            cert.isValid,
            cert.issuer
        );
    }

    function serialNumberToPassportId(string memory serialNumber) external view returns (uint256) {
        return _serialNumberToPassportId[serialNumber];
    }

    function authorizedBrands(address brand) external view returns (bool) {
        return _authorizedBrands[brand];
    }

    function authorizedManufacturers(address manufacturer) external view returns (bool) {
        return _authorizedManufacturers[manufacturer];
    }

    function authorizedCertifiers(address certifier) external view returns (bool) {
        return _authorizedCertifiers[certifier];
    }

    function authorizedOperators(address operator) external view returns (bool) {
        return _authorizedOperators[operator];
    }

    function brandIdToAddress(string memory brandId) external view returns (address) {
        return _brandIdToAddress[brandId];
    }

    function addressToBrandId(address brandAddress) external view returns (string memory) {
        return _addressToBrandId[brandAddress];
    }

    function passportCreationFee() external view returns (uint256) {
        return _passportCreationFee;
    }

    function certificateCreationFee() external view returns (uint256) {
        return _certificateCreationFee;
    }

    function emergencyStop() external view returns (bool) {
        return _emergencyStop;
    }

    // ============ PRODUCT PASSPORT MANAGEMENT ============

    /**
     * @dev Create a new product passport
     * @param serialNumber Unique serial number of the product
     * @param brandId Brand identifier
     * @param productName Name of the product
     * @param productDescription Description of the product
     * @param materials Materials used in the product
     * @param manufacturingLocation Location where the product was manufactured
     * @param manufacturingDate Date when the product was manufactured
     * @param ipfsCID IPFS CID containing passport metadata
     * @param metadataHash Hash of the metadata for verification
     */
    function createProductPassport(
        string memory serialNumber,
        string memory brandId,
        string memory productName,
        string memory productDescription,
        string memory materials,
        string memory manufacturingLocation,
        uint256 manufacturingDate,
        string memory ipfsCID,
        string memory metadataHash
    ) external payable onlyAuthorizedBrand validBrand(brandId) notEmergencyStopped nonReentrant returns (uint256) {
        require(msg.value >= _passportCreationFee, "Insufficient fee");
        require(bytes(serialNumber).length > 0, "Serial number cannot be empty");
        require(_serialNumberToPassportId[serialNumber] == 0, "Serial number already exists");
        require(bytes(productName).length > 0, "Product name cannot be empty");
        require(bytes(ipfsCID).length > 0, "IPFS CID cannot be empty");
        require(manufacturingDate <= block.timestamp, "Manufacturing date cannot be in the future");

        _passportIds = _passportIds + 1;
        uint256 passportId = _passportIds;

        ProductPassport storage newPassport = _productPassports[passportId];
        newPassport.passportId = passportId;
        newPassport.serialNumber = serialNumber;
        newPassport.brandId = brandId;
        newPassport.productName = productName;
        newPassport.productDescription = productDescription;
        newPassport.materials = materials;
        newPassport.manufacturingLocation = manufacturingLocation;
        newPassport.manufacturingDate = manufacturingDate;
        newPassport.creationTimestamp = block.timestamp;
        newPassport.ipfsCID = ipfsCID;
        newPassport.metadataHash = metadataHash;
        newPassport.isValid = true;
        newPassport.isRecalled = false;
        newPassport.creator = msg.sender;
        newPassport.brandAddress = _brandIdToAddress[brandId];

        // Map serial number to passport ID
        _serialNumberToPassportId[serialNumber] = passportId;

        emit ProductPassportCreated(
            passportId,
            serialNumber,
            brandId,
            productName,
            ipfsCID,
            msg.sender
        );

        return passportId;
    }

    /**
     * @dev Update product passport metadata
     * @param passportId ID of the passport to update
     * @param ipfsCID New IPFS CID
     * @param metadataHash New metadata hash
     */
    function updateProductPassport(
        uint256 passportId,
        string memory ipfsCID,
        string memory metadataHash
    ) external validPassport(passportId) notEmergencyStopped {
        ProductPassport storage passport = _productPassports[passportId];
        require(msg.sender == passport.creator || msg.sender == owner(), "Not authorized");
        require(bytes(ipfsCID).length > 0, "IPFS CID cannot be empty");

        passport.ipfsCID = ipfsCID;
        passport.metadataHash = metadataHash;

        emit ProductPassportUpdated(passportId, ipfsCID, metadataHash);
    }

    /**
     * @dev Invalidate a product passport
     * @param passportId ID of the passport to invalidate
     * @param reason Reason for invalidation
     */
    function invalidateProductPassport(
        uint256 passportId,
        string memory reason
    ) external validPassport(passportId) notEmergencyStopped {
        ProductPassport storage passport = _productPassports[passportId];
        require(
            msg.sender == passport.creator || 
            msg.sender == passport.brandAddress || 
            msg.sender == owner(),
            "Not authorized"
        );

        passport.isValid = false;

        emit ProductPassportInvalidated(passportId, reason);
    }

    // ============ BRAND MANAGEMENT ============

    /**
     * @dev Register a new brand
     * @param brandId Unique brand identifier
     * @param brandName Name of the brand
     * @param brandDescription Description of the brand
     * @param ipfsCID IPFS CID containing brand metadata
     * @param authorizedCountries Array of authorized countries
     */
    function registerBrand(
        string memory brandId,
        string memory brandName,
        string memory brandDescription,
        string memory ipfsCID,
        string[] memory authorizedCountries
    ) external notEmergencyStopped returns (bool) {
        require(bytes(brandId).length > 0, "Brand ID cannot be empty");
        require(bytes(_brands[brandId].brandId).length == 0, "Brand ID already exists");
        require(bytes(brandName).length > 0, "Brand name cannot be empty");
        require(bytes(ipfsCID).length > 0, "IPFS CID cannot be empty");
        require(_brandIdToAddress[brandId] == address(0), "Brand ID already registered");

        Brand storage newBrand = _brands[brandId];
        newBrand.brandId = brandId;
        newBrand.brandName = brandName;
        newBrand.brandDescription = brandDescription;
        newBrand.ipfsCID = ipfsCID;
        newBrand.isActive = true;
        newBrand.isVerified = false;
        newBrand.brandAddress = msg.sender;
        newBrand.registrationDate = block.timestamp;

        // Set authorized countries
        for (uint256 i = 0; i < authorizedCountries.length; i++) {
            if (bytes(authorizedCountries[i]).length > 0) {
                newBrand.authorizedCountries.push(authorizedCountries[i]);
                newBrand.countryAuthorizations[authorizedCountries[i]] = true;
            }
        }

        // Map brand ID to address
        _brandIdToAddress[brandId] = msg.sender;
        _addressToBrandId[msg.sender] = brandId;

        emit BrandRegistered(brandId, brandName, msg.sender, ipfsCID);
        return true;
    }

    /**
     * @dev Verify a brand (only owner can verify)
     * @param brandId Brand identifier to verify
     */
    function verifyBrand(string memory brandId) external onlyOwner validBrand(brandId) {
        require(!_brands[brandId].isVerified, "Brand already verified");

        _brands[brandId].isVerified = true;
        emit BrandVerified(brandId);
    }

    // ============ CERTIFICATE MANAGEMENT ============

    /**
     * @dev Create a manufacturing certificate
     * @param passportId ID of the product passport
     * @param certificateType Type of certificate
     * @param certificateNumber Certificate number
     * @param issuingAuthority Authority that issued the certificate
     * @param issueDate Date when certificate was issued
     * @param expiryDate Date when certificate expires
     * @param ipfsCID IPFS CID containing certificate metadata
     */
    function createManufacturingCertificate(
        uint256 passportId,
        string memory certificateType,
        string memory certificateNumber,
        string memory issuingAuthority,
        uint256 issueDate,
        uint256 expiryDate,
        string memory ipfsCID
    ) external payable onlyAuthorizedCertifier validPassport(passportId) notEmergencyStopped nonReentrant returns (uint256) {
        require(msg.value >= _certificateCreationFee, "Insufficient fee");
        require(bytes(certificateType).length > 0, "Certificate type cannot be empty");
        require(bytes(certificateNumber).length > 0, "Certificate number cannot be empty");
        require(bytes(issuingAuthority).length > 0, "Issuing authority cannot be empty");
        require(bytes(ipfsCID).length > 0, "IPFS CID cannot be empty");
        require(issueDate <= block.timestamp, "Issue date cannot be in the future");
        require(expiryDate > issueDate, "Expiry date must be after issue date");

        _certificateIds = _certificateIds + 1;
        uint256 certificateId = _certificateIds;

        ManufacturingCertificate storage newCert = _certificates[certificateId];
        newCert.certificateId = certificateId;
        newCert.passportId = passportId;
        newCert.certificateType = certificateType;
        newCert.certificateNumber = certificateNumber;
        newCert.issuingAuthority = issuingAuthority;
        newCert.issueDate = issueDate;
        newCert.expiryDate = expiryDate;
        newCert.ipfsCID = ipfsCID;
        newCert.isValid = true;
        newCert.issuer = msg.sender;

        emit ManufacturingCertificateCreated(
            certificateId,
            passportId,
            certificateType,
            certificateNumber,
            ipfsCID,
            msg.sender
        );

        return certificateId;
    }

    /**
     * @dev Invalidate a manufacturing certificate
     * @param certificateId ID of the certificate to invalidate
     */
    function invalidateCertificate(uint256 certificateId) external {
        require(_certificates[certificateId].certificateId != 0, "Certificate does not exist");
        require(
            msg.sender == _certificates[certificateId].issuer || 
            msg.sender == owner(),
            "Not authorized"
        );

        _certificates[certificateId].isValid = false;
        emit CertificateInvalidated(certificateId);
    }

    // ============ ACCESS CONTROL FUNCTIONS ============

    /**
     * @dev Authorize a brand address
     * @param brand Address of the brand to authorize
     */
    function authorizeBrand(address brand) external onlyOwner {
        require(brand != address(0), "Invalid brand address");
        require(!_authorizedBrands[brand], "Brand already authorized");

        _authorizedBrands[brand] = true;
        emit BrandAuthorized(brand);
    }

    /**
     * @dev Revoke brand authorization
     * @param brand Address of the brand to revoke
     */
    function revokeBrand(address brand) external onlyOwner {
        require(_authorizedBrands[brand], "Brand not authorized");

        _authorizedBrands[brand] = false;
        emit BrandRevoked(brand);
    }

    /**
     * @dev Authorize a manufacturer address
     * @param manufacturer Address of the manufacturer to authorize
     */
    function authorizeManufacturer(address manufacturer) external onlyOwner {
        require(manufacturer != address(0), "Invalid manufacturer address");
        require(!_authorizedManufacturers[manufacturer], "Manufacturer already authorized");

        _authorizedManufacturers[manufacturer] = true;
        emit ManufacturerAuthorized(manufacturer);
    }

    /**
     * @dev Revoke manufacturer authorization
     * @param manufacturer Address of the manufacturer to revoke
     */
    function revokeManufacturer(address manufacturer) external onlyOwner {
        require(_authorizedManufacturers[manufacturer], "Manufacturer not authorized");

        _authorizedManufacturers[manufacturer] = false;
        emit ManufacturerRevoked(manufacturer);
    }

    /**
     * @dev Authorize a certifier address
     * @param certifier Address of the certifier to authorize
     */
    function authorizeCertifier(address certifier) external onlyOwner {
        require(certifier != address(0), "Invalid certifier address");
        require(!_authorizedCertifiers[certifier], "Certifier already authorized");

        _authorizedCertifiers[certifier] = true;
        emit CertifierAuthorized(certifier);
    }

    /**
     * @dev Revoke certifier authorization
     * @param certifier Address of the certifier to revoke
     */
    function revokeCertifier(address certifier) external onlyOwner {
        require(_authorizedCertifiers[certifier], "Certifier not authorized");

        _authorizedCertifiers[certifier] = false;
        emit CertifierRevoked(certifier);
    }

    /**
     * @dev Authorize an operator address
     * @param operator Address of the operator to authorize
     */
    function authorizeOperator(address operator) external onlyOwner {
        require(operator != address(0), "Invalid operator address");
        require(!_authorizedOperators[operator], "Operator already authorized");

        _authorizedOperators[operator] = true;
        emit OperatorAuthorized(operator);
    }

    /**
     * @dev Revoke operator authorization
     * @param operator Address of the operator to revoke
     */
    function revokeOperator(address operator) external onlyOwner {
        require(_authorizedOperators[operator], "Operator not authorized");

        _authorizedOperators[operator] = false;
        emit OperatorRevoked(operator);
    }

    /**
     * @dev Update passport creation fee
     * @param newFee New fee amount
     */
    function updatePassportCreationFee(uint256 newFee) external onlyOwner {
        _passportCreationFee = newFee;
    }

    /**
     * @dev Update certificate creation fee
     * @param newFee New fee amount
     */
    function updateCertificateCreationFee(uint256 newFee) external onlyOwner {
        _certificateCreationFee = newFee;
    }

    /**
     * @dev Activate emergency stop
     */
    function activateEmergencyStop() external onlyOwner {
        require(!_emergencyStop, "Emergency stop already active");
        _emergencyStop = true;
        emit EmergencyStopActivated();
    }

    /**
     * @dev Deactivate emergency stop
     */
    function deactivateEmergencyStop() external onlyOwner {
        require(_emergencyStop, "Emergency stop not active");
        _emergencyStop = false;
        emit EmergencyStopDeactivated();
    }

    /**
     * @dev Pause contract
     */
    function pause() external onlyOwner {
        _pause();
    }

    /**
     * @dev Unpause contract
     */
    function unpause() external onlyOwner {
        _unpause();
    }

    // ============ EMERGENCY FUNCTIONS ============

    /**
     * @dev Emergency function to recover stuck ETH
     * @param to Address to send ETH to
     * @param amount Amount to recover
     */
    function emergencyRecoverETH(address to, uint256 amount) external onlyOwner {
        require(to != address(0), "Invalid recipient");
        require(amount > 0, "Amount must be greater than 0");
        require(amount <= address(this).balance, "Insufficient balance");

        (bool success, ) = payable(to).call{value: amount}("");
        require(success, "Transfer failed");
    }

    // ============ RECEIVE FUNCTION ============

    receive() external payable {
        // Contract can receive ETH for fees
    }
}

contracts/TrataTechProductPassportUpgrad.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/PausableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/ReentrancyGuardUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";


/**
 * @title TrataTechProductPassportUpgradeable
 * @dev Upgradeable contract for managing digital product passports, brands, and manufacturing certificates
 * @dev Uses UUPS upgradeable pattern for future upgrades
 */
contract TrataTechProductPassportUpgradeable is 
    Initializable, 
    OwnableUpgradeable, 
    PausableUpgradeable, 
    ReentrancyGuardUpgradeable,
    UUPSUpgradeable 
{


    // ============ STRUCTS ============

    struct ProductPassport {
        uint256 id;
        string serialNumber;
        string brandId;
        string productName;
        string productDescription;
        string materials;
        string manufacturingLocation;
        uint256 manufacturingDate;
        string ipfsCID;
        bytes32 metadataHash;
        string[] additionalAttributes;
        bool isValid;
        uint256 createdAt;
        uint256 updatedAt;
    }

    struct Brand {
        string id;
        string name;
        string description;
        string ipfsCID;
        string[] authorizedCountries;
        bool isVerified;
        bool isActive;
        uint256 reserved; // was registrationFee
        uint256 createdAt;
    }

    struct ManufacturingCertificate {
        uint256 id;
        uint256 passportId;
        string certificateType;
        string certificateNumber;
        string issuingAuthority;
        uint256 issueDate;
        uint256 expiryDate;
        string ipfsCID;
        bool isValid;
        uint256 createdAt;
    }

    // ============ STATE VARIABLES ============

    uint256 private _passportIds;
    uint256 private _certificateIds;

    // Brand management
    mapping(string => Brand) public brands;
    mapping(address => bool) public authorizedBrands;
    mapping(address => bool) public authorizedOperators;
    mapping(address => bool) public authorizedManufacturers;
    mapping(address => bool) public authorizedCertifiers;

    // Product passport management
    mapping(uint256 => ProductPassport) public productPassports;
    mapping(string => uint256) public serialNumberToPassportId;
    mapping(string => uint256[]) public brandPassports;

    // Manufacturing certificate management
    mapping(uint256 => ManufacturingCertificate) public certificates;
    mapping(uint256 => uint256[]) public passportCertificates;

    // Reserved for future use
    uint256[50] private __gap;

    // Emergency controls
    bool public emergencyStop;

    // ============ EVENTS ============

    event BrandRegistered(string indexed brandId, string name, address indexed registrant, uint256 fee);
    event BrandVerified(string indexed brandId, address indexed verifier);
    event BrandRevoked(string indexed brandId, address indexed revoker, string reason);
    event ProductPassportCreated(uint256 indexed passportId, string serialNumber, string indexed brandId, string ipfsCID);
    event ProductPassportUpdated(uint256 indexed passportId, string ipfsCID, uint256 updatedAt);
    event ProductPassportInvalidated(uint256 indexed passportId, string reason, address indexed invalidator);
    event ManufacturingCertificateCreated(uint256 indexed certificateId, uint256 indexed passportId, string certificateType, string ipfsCID);
    event ManufacturingCertificateInvalidated(uint256 indexed certificateId, string reason, address indexed invalidator);
    event OperatorAuthorized(address indexed operator, address indexed authorizer);
    event OperatorRevoked(address indexed operator, address indexed revoker);
    event EmergencyStopActivated(address indexed activator);
    event EmergencyStopDeactivated(address indexed deactivator);
    event FeesUpdated(uint256 brandRegistrationFee, uint256 passportCreationFee, uint256 certificateCreationFee);
    event FeeCollected(address indexed collector, uint256 amount);

    // ============ MODIFIERS ============

    modifier onlyAuthorizedBrand() {
        require(authorizedBrands[msg.sender] || owner() == msg.sender, "Not authorized brand");
        _;
    }

    modifier onlyAuthorizedOperator() {
        require(authorizedOperators[msg.sender] || owner() == msg.sender, "Not authorized operator");
        _;
    }

    modifier onlyAuthorizedManufacturer() {
        require(authorizedManufacturers[msg.sender] || owner() == msg.sender, "Not authorized manufacturer");
        _;
    }

    modifier onlyAuthorizedCertifier() {
        require(authorizedCertifiers[msg.sender] || owner() == msg.sender, "Not authorized certifier");
        _;
    }

    modifier whenNotEmergencyStopped() {
        require(!emergencyStop, "Contract is emergency stopped");
        _;
    }

    modifier validPassportId(uint256 passportId) {
        require(passportId > 0 && passportId <= _passportIds, "Invalid passport ID");
        _;
    }

    modifier validCertificateId(uint256 certificateId) {
        require(certificateId > 0 && certificateId <= _certificateIds, "Invalid certificate ID");
        _;
    }

    // ============ INITIALIZATION ============

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    function initialize(address initialOwner) public initializer {
        __Ownable_init(initialOwner);
        __Pausable_init();
        __ReentrancyGuard_init();
        __UUPSUpgradeable_init();

        // Initialize counters in the initializer
        _passportIds = 0;
        _certificateIds = 0;

        // Fee initialization removed - no blockchain payments

        // Authorize initial owner as operator
        authorizedOperators[initialOwner] = true;
        authorizedBrands[initialOwner] = true;
        authorizedManufacturers[initialOwner] = true;
        authorizedCertifiers[initialOwner] = true;
    }

    // ============ UUPS UPGRADEABLE ============

    function _authorizeUpgrade(address newImplementation) internal override onlyOwner {}

    // ============ BRAND MANAGEMENT ============

    /**
     * @dev Register a new brand with fee payment
     * @param brandId Unique brand identifier
     * @param brandName Brand name
     * @param brandDescription Brand description
     * @param ipfsCID IPFS CID for brand metadata
     * @param authorizedCountries Array of authorized countries
     */
    function registerBrand(
        string memory brandId,
        string memory brandName,
        string memory brandDescription,
        string memory ipfsCID,
        string[] memory authorizedCountries
    ) external whenNotPaused whenNotEmergencyStopped nonReentrant {
        // Registration fee requirement removed
        require(bytes(brandId).length > 0, "Brand ID cannot be empty");
        require(bytes(brandName).length > 0, "Brand name cannot be empty");
        require(brands[brandId].createdAt == 0, "Brand already exists");

        // Create brand
        brands[brandId] = Brand({
            id: brandId,
            name: brandName,
            description: brandDescription,
            ipfsCID: ipfsCID,
            authorizedCountries: authorizedCountries,
            isVerified: false,
            isActive: true,
            reserved: 0, // was registrationFee
            createdAt: block.timestamp
        });

        // Authorize registrant as brand operator
        authorizedBrands[msg.sender] = true;

        // Fee collection removed

        emit BrandRegistered(brandId, brandName, msg.sender, 0);
    }

    /**
     * @dev Verify a brand (owner only)
     * @param brandId Brand identifier to verify
     */
    function verifyBrand(string memory brandId) external onlyOwner {
        require(brands[brandId].createdAt > 0, "Brand does not exist");
        require(!brands[brandId].isVerified, "Brand already verified");

        brands[brandId].isVerified = true;

        emit BrandVerified(brandId, msg.sender);
    }

    /**
     * @dev Revoke a brand (owner only)
     * @param brandId Brand identifier to revoke
     * @param reason Reason for revocation
     */
    function revokeBrand(string memory brandId, string memory reason) external onlyOwner {
        require(brands[brandId].createdAt > 0, "Brand does not exist");

        brands[brandId].isActive = false;

        emit BrandRevoked(brandId, msg.sender, reason);
    }

    // ============ PRODUCT PASSPORT MANAGEMENT ============

    /**
     * @dev Create a new product passport
     * @param serialNumber Product serial number
     * @param brandId Associated brand ID
     * @param productName Product name
     * @param productDescription Product description
     * @param materials Materials used
     * @param manufacturingLocation Manufacturing location
     * @param manufacturingDate Manufacturing date
     * @param ipfsCID IPFS CID for passport metadata
     * @param metadataHash Hash of metadata for verification
     * @param additionalAttributes Additional product attributes
     */
    function createProductPassport(
        string memory serialNumber,
        string memory brandId,
        string memory productName,
        string memory productDescription,
        string memory materials,
        string memory manufacturingLocation,
        uint256 manufacturingDate,
        string memory ipfsCID,
        bytes32 metadataHash,
        string[] memory additionalAttributes
    ) external whenNotPaused whenNotEmergencyStopped nonReentrant onlyAuthorizedBrand {
        // Creation fee requirement removed
        require(bytes(serialNumber).length > 0, "Serial number cannot be empty");
        require(brands[brandId].isActive, "Brand is not active");
        require(serialNumberToPassportId[serialNumber] == 0, "Serial number already exists");
        require(manufacturingDate <= block.timestamp, "Manufacturing date cannot be in future");

        _passportIds = _passportIds + 1;
        uint256 passportId = _passportIds;

        // Create product passport
        productPassports[passportId] = ProductPassport({
            id: passportId,
            serialNumber: serialNumber,
            brandId: brandId,
            productName: productName,
            productDescription: productDescription,
            materials: materials,
            manufacturingLocation: manufacturingLocation,
            manufacturingDate: manufacturingDate,
            ipfsCID: ipfsCID,
            metadataHash: metadataHash,
            additionalAttributes: additionalAttributes,
            isValid: true,
            createdAt: block.timestamp,
            updatedAt: block.timestamp
        });

        // Update mappings
        serialNumberToPassportId[serialNumber] = passportId;
        brandPassports[brandId].push(passportId);

        // Fee collection removed

        emit ProductPassportCreated(passportId, serialNumber, brandId, ipfsCID);
    }

    /**
     * @dev Update product passport metadata
     * @param passportId Passport ID to update
     * @param ipfsCID New IPFS CID
     * @param metadataHash New metadata hash
     * @param additionalAttributes New additional attributes
     */
    function updateProductPassport(
        uint256 passportId,
        string memory ipfsCID,
        bytes32 metadataHash,
        string[] memory additionalAttributes
    ) external validPassportId(passportId) onlyAuthorizedOperator {
        require(productPassports[passportId].isValid, "Passport is invalid");

        ProductPassport storage passport = productPassports[passportId];
        passport.ipfsCID = ipfsCID;
        passport.metadataHash = metadataHash;
        passport.additionalAttributes = additionalAttributes;
        passport.updatedAt = block.timestamp;

        emit ProductPassportUpdated(passportId, ipfsCID, block.timestamp);
    }

    /**
     * @dev Invalidate a product passport
     * @param passportId Passport ID to invalidate
     * @param reason Reason for invalidation
     */
    function invalidateProductPassport(
        uint256 passportId,
        string memory reason
    ) external validPassportId(passportId) onlyAuthorizedOperator {
        require(productPassports[passportId].isValid, "Passport already invalid");

        productPassports[passportId].isValid = false;
        productPassports[passportId].updatedAt = block.timestamp;

        emit ProductPassportInvalidated(passportId, reason, msg.sender);
    }

    // ============ MANUFACTURING CERTIFICATE MANAGEMENT ============

    /**
     * @dev Create a manufacturing certificate
     * @param passportId Associated passport ID
     * @param certificateType Type of certificate
     * @param certificateNumber Certificate number
     * @param issuingAuthority Issuing authority
     * @param issueDate Issue date
     * @param expiryDate Expiry date
     * @param ipfsCID IPFS CID for certificate metadata
     */
    function createManufacturingCertificate(
        uint256 passportId,
        string memory certificateType,
        string memory certificateNumber,
        string memory issuingAuthority,
        uint256 issueDate,
        uint256 expiryDate,
        string memory ipfsCID
    ) external validPassportId(passportId) whenNotPaused whenNotEmergencyStopped nonReentrant onlyAuthorizedCertifier {
        // Creation fee requirement removed
        require(productPassports[passportId].isValid, "Passport is invalid");
        require(issueDate <= block.timestamp, "Issue date cannot be in future");
        require(expiryDate > issueDate, "Expiry date must be after issue date");

        _certificateIds = _certificateIds + 1;
        uint256 certificateId = _certificateIds;

        // Create certificate
        certificates[certificateId] = ManufacturingCertificate({
            id: certificateId,
            passportId: passportId,
            certificateType: certificateType,
            certificateNumber: certificateNumber,
            issuingAuthority: issuingAuthority,
            issueDate: issueDate,
            expiryDate: expiryDate,
            ipfsCID: ipfsCID,
            isValid: true,
            createdAt: block.timestamp
        });

        // Update passport certificates mapping
        passportCertificates[passportId].push(certificateId);

        // Fee collection removed

        emit ManufacturingCertificateCreated(certificateId, passportId, certificateType, ipfsCID);
    }

    /**
     * @dev Invalidate a manufacturing certificate
     * @param certificateId Certificate ID to invalidate
     * @param reason Reason for invalidation
     */
    function invalidateCertificate(
        uint256 certificateId,
        string memory reason
    ) external validCertificateId(certificateId) onlyAuthorizedCertifier {
        require(certificates[certificateId].isValid, "Certificate already invalid");

        certificates[certificateId].isValid = false;

        emit ManufacturingCertificateInvalidated(certificateId, reason, msg.sender);
    }

    // ============ ACCESS CONTROL ============

    /**
     * @dev Authorize an operator
     * @param operator Address to authorize
     */
    function authorizeOperator(address operator) external onlyOwner {
        require(operator != address(0), "Invalid operator address");
        authorizedOperators[operator] = true;
        emit OperatorAuthorized(operator, msg.sender);
    }

    /**
     * @dev Revoke operator authorization
     * @param operator Address to revoke
     */
    function revokeOperator(address operator) external onlyOwner {
        authorizedOperators[operator] = false;
        emit OperatorRevoked(operator, msg.sender);
    }

    /**
     * @dev Authorize a brand
     * @param brand Address to authorize
     */
    function authorizeBrand(address brand) external onlyOwner {
        require(brand != address(0), "Invalid brand address");
        authorizedBrands[brand] = true;
    }

    /**
     * @dev Revoke brand authorization
     * @param brand Address to revoke
     */
    function revokeBrand(address brand) external onlyOwner {
        authorizedBrands[brand] = false;
    }

    /**
     * @dev Authorize a manufacturer
     * @param manufacturer Address to authorize
     */
    function authorizeManufacturer(address manufacturer) external onlyOwner {
        require(manufacturer != address(0), "Invalid manufacturer address");
        authorizedManufacturers[manufacturer] = true;
    }

    /**
     * @dev Revoke manufacturer authorization
     * @param manufacturer Address to revoke
     */
    function revokeManufacturer(address manufacturer) external onlyOwner {
        authorizedManufacturers[manufacturer] = false;
    }

    /**
     * @dev Authorize a certifier
     * @param certifier Address to authorize
     */
    function authorizeCertifier(address certifier) external onlyOwner {
        require(certifier != address(0), "Invalid certifier address");
        authorizedCertifiers[certifier] = true;
    }

    /**
     * @dev Revoke certifier authorization
     * @param certifier Address to revoke
     */
    function revokeCertifier(address certifier) external onlyOwner {
        authorizedCertifiers[certifier] = false;
    }

    // ============ EMERGENCY CONTROLS ============

    /**
     * @dev Activate emergency stop
     */
    function activateEmergencyStop() external onlyOwner {
        emergencyStop = true;
        emit EmergencyStopActivated(msg.sender);
    }

    /**
     * @dev Deactivate emergency stop
     */
    function deactivateEmergencyStop() external onlyOwner {
        emergencyStop = false;
        emit EmergencyStopDeactivated(msg.sender);
    }

    /**
     * @dev Pause contract
     */
    function pause() external onlyOwner {
        _pause();
    }

    /**
     * @dev Unpause contract
     */
    function unpause() external onlyOwner {
        _unpause();
    }

    // ============ FEE MANAGEMENT ============

    // Fee update functions removed - no blockchain payments

    // Fee collector functions removed - no blockchain payments

    // Fee withdrawal functions removed - no blockchain payments

    // ============ INTERNAL FUNCTIONS ============

    // Fee collection internal functions removed - no blockchain payments

    // ============ VIEW FUNCTIONS ============

    /**
     * @dev Get product passport details
     * @param passportId Passport ID
     * @return passport Product passport details
     */
    function getProductPassportDetails(uint256 passportId) external view validPassportId(passportId) returns (ProductPassport memory passport) {
        return productPassports[passportId];
    }

    /**
     * @dev Get brand details
     * @param brandId Brand ID
     * @return brand Brand details
     */
    function getBrandDetails(string memory brandId) external view returns (Brand memory brand) {
        require(brands[brandId].createdAt > 0, "Brand does not exist");
        return brands[brandId];
    }

    /**
     * @dev Get certificate details
     * @param certificateId Certificate ID
     * @return certificate Certificate details
     */
    function getCertificateDetails(uint256 certificateId) external view validCertificateId(certificateId) returns (ManufacturingCertificate memory certificate) {
        return certificates[certificateId];
    }

    /**
     * @dev Get passports for a brand
     * @param brandId Brand ID
     * @return passportIds Array of passport IDs
     */
    function getBrandPassports(string memory brandId) external view returns (uint256[] memory passportIds) {
        return brandPassports[brandId];
    }

    /**
     * @dev Get certificates for a passport
     * @param passportId Passport ID
     * @return certificateIds Array of certificate IDs
     */
    function getPassportCertificates(uint256 passportId) external view validPassportId(passportId) returns (uint256[] memory certificateIds) {
        return passportCertificates[passportId];
    }

    /**
     * @dev Get passport ID by serial number
     * @param serialNumber Serial number
     * @return passportId Passport ID
     */
    function getPassportIdBySerialNumber(string memory serialNumber) external view returns (uint256 passportId) {
        return serialNumberToPassportId[serialNumber];
    }

    /**
     * @dev Get total number of passports
     * @return count Total passport count
     */
    function getTotalPassports() external view returns (uint256 count) {
        return _passportIds;
    }

    /**
     * @dev Get total number of certificates
     * @return count Total certificate count
     */
    function getTotalCertificates() external view returns (uint256 count) {
        return _certificateIds;
    }

    /**
     * @dev Check if address is authorized brand
     * @param account Address to check
     * @return isAuthorized Whether address is authorized
     */
    function isAuthorizedBrand(address account) external view returns (bool isAuthorized) {
        return authorizedBrands[account];
    }

    /**
     * @dev Check if address is authorized operator
     * @param account Address to check
     * @return isAuthorized Whether address is authorized
     */
    function isAuthorizedOperator(address account) external view returns (bool isAuthorized) {
        return authorizedOperators[account];
    }

    // ============ EMERGENCY RECOVERY ============

    /**
     * @dev Emergency function to recover tokens
     * @param tokenAddress Token contract address
     * @param to Recipient address
     * @param amount Amount to recover
     */
    function emergencyRecoverTokens(
        address tokenAddress,
        address to,
        uint256 amount
    ) external onlyOwner {
        require(to != address(0), "Invalid recipient address");

        // This would require IERC20 interface implementation
        // For now, this is a placeholder for emergency token recovery
    }

    /**
     * @dev Emergency function to recover ETH
     * @param to Recipient address
     * @param amount Amount to recover
     */
    function emergencyRecoverETH(address to, uint256 amount) external onlyOwner {
        require(to != address(0), "Invalid recipient address");
        require(amount <= address(this).balance, "Insufficient balance");

        (bool success, ) = to.call{value: amount}("");
        require(success, "ETH recovery failed");
    }

    // Duplicate gap removed
}

contracts/TrataTechProvenance.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import "@openzeppelin/contracts/utils/Strings.sol";

/**
 * @title TrataTechProvenance
 * @dev Provenance Contract for maintaining immutable logs of transfers and service history
 * @author Advanced Developer
 */
contract TrataTechProvenance is Ownable, Pausable, ReentrancyGuard {

    using ECDSA for bytes32;
    using Strings for uint256;

    // ============ STRUCTS ============

    struct ProvenanceEntry {
        uint256 entryId;
        uint256 passportId;
        ProvenanceType entryType;
        address from;
        address to;
        uint256 timestamp;
        string location;
        string description;
        string ipfsCID;
        string metadataHash;
        bool isValid;
        address recorder;
        mapping(string => string) additionalData;
        string[] dataKeys;
    }

    struct ServiceRecord {
        uint256 serviceId;
        uint256 passportId;
        string serviceType;
        string serviceProvider;
        string serviceDescription;
        uint256 serviceDate;
        uint256 nextServiceDate;
        string ipfsCID;
        string certificateNumber;
        bool isValid;
        address serviceProviderAddress;
        mapping(string => string) serviceDetails;
        string[] detailKeys;
    }

    struct TransferHistory {
        uint256 passportId;
        uint256[] transferEntryIds;
        uint256[] serviceEntryIds;
        uint256 totalTransfers;
        uint256 totalServices;
        address currentOwner;
        uint256 lastTransferDate;
    }

    enum ProvenanceType {
        MANUFACTURING,
        TRANSFER,
        SERVICE,
        REPAIR,
        MAINTENANCE,
        INSPECTION,
        CERTIFICATION,
        RECALL,
        DISPOSAL,
        CUSTOM
    }

    // ============ STATE VARIABLES ============

    uint256 private _entryIds = 0;
    uint256 private _serviceIds = 0;

    // Mappings
    mapping(uint256 => ProvenanceEntry) public provenanceEntries;
    mapping(uint256 => ServiceRecord) public serviceRecords;
    mapping(uint256 => TransferHistory) public transferHistories;
    mapping(uint256 => uint256[]) public passportToEntries;
    mapping(uint256 => uint256[]) public passportToServices;
    mapping(address => bool) public authorizedRecorders;
    mapping(address => bool) public authorizedServiceProviders;
    mapping(address => bool) public authorizedOperators;

    // Fee structure
    uint256 public provenanceEntryFee = 0.001 ether;
    uint256 public serviceRecordFee = 0.002 ether;

    // Emergency controls
    bool public emergencyStop = false;

    // ============ EVENTS ============

    event ProvenanceEntryCreated(
        uint256 indexed entryId,
        uint256 indexed passportId,
        ProvenanceType entryType,
        address indexed from,
        address to,
        string location,
        string ipfsCID
    );

    event ProvenanceEntryUpdated(
        uint256 indexed entryId,
        string ipfsCID,
        address indexed updater
    );

    event ProvenanceEntryInvalidated(
        uint256 indexed entryId,
        string reason,
        address indexed invalidator
    );

    event ServiceRecordCreated(
        uint256 indexed serviceId,
        uint256 indexed passportId,
        string serviceType,
        string serviceProvider,
        string ipfsCID
    );

    event ServiceRecordUpdated(
        uint256 indexed serviceId,
        string ipfsCID,
        address indexed updater
    );

    event ServiceRecordInvalidated(
        uint256 indexed serviceId,
        string reason,
        address indexed invalidator
    );

    event TransferCompleted(
        uint256 indexed passportId,
        address indexed from,
        address indexed to,
        uint256 entryId
    );

    event AdditionalDataAdded(
        uint256 indexed entryId,
        string key,
        string value
    );

    // ============ MODIFIERS ============

    modifier onlyAuthorizedRecorder() {
        require(authorizedRecorders[msg.sender] || msg.sender == owner(), "Not authorized recorder");
        _;
    }

    modifier onlyAuthorizedServiceProvider() {
        require(authorizedServiceProviders[msg.sender] || msg.sender == owner(), "Not authorized service provider");
        _;
    }

    modifier onlyAuthorizedOperator() {
        require(authorizedOperators[msg.sender] || msg.sender == owner(), "Not authorized operator");
        _;
    }

    modifier notEmergencyStopped() {
        require(!emergencyStop, "Contract is emergency stopped");
        _;
    }

    modifier validEntry(uint256 entryId) {
        require(provenanceEntries[entryId].entryId != 0, "Provenance entry does not exist");
        require(provenanceEntries[entryId].isValid, "Provenance entry is invalid");
        _;
    }

    modifier validService(uint256 serviceId) {
        require(serviceRecords[serviceId].serviceId != 0, "Service record does not exist");
        require(serviceRecords[serviceId].isValid, "Service record is invalid");
        _;
    }

    // ============ CONSTRUCTOR ============

    constructor() Ownable(msg.sender) {
        _entryIds = 1; // Start from 1
        _serviceIds = 1; // Start from 1
    }

    // ============ PROVENANCE ENTRY MANAGEMENT ============

    /**
     * @dev Create a new provenance entry
     * @param passportId Product passport ID
     * @param entryType Type of provenance entry
     * @param from Source address
     * @param to Destination address
     * @param location Location of the event
     * @param description Description of the event
     * @param ipfsCID IPFS CID containing entry metadata
     * @param metadataHash Hash of the metadata for integrity verification
     * @param additionalData Array of key-value pairs for additional data
     */
    function createProvenanceEntry(
        uint256 passportId,
        ProvenanceType entryType,
        address from,
        address to,
        string memory location,
        string memory description,
        string memory ipfsCID,
        string memory metadataHash,
        string[] memory additionalData
    ) external onlyAuthorizedRecorder notEmergencyStopped nonReentrant {
        require(passportId > 0, "Invalid passport ID");
        require(bytes(location).length > 0, "Location cannot be empty");
        require(bytes(description).length > 0, "Description cannot be empty");
        require(bytes(ipfsCID).length > 0, "IPFS CID cannot be empty");
        require(bytes(metadataHash).length > 0, "Metadata hash cannot be empty");

        _entryIds = _entryIds + 1;
        uint256 entryId = _entryIds;

        ProvenanceEntry storage newEntry = provenanceEntries[entryId];
        newEntry.entryId = entryId;
        newEntry.passportId = passportId;
        newEntry.entryType = entryType;
        newEntry.from = from;
        newEntry.to = to;
        newEntry.timestamp = block.timestamp;
        newEntry.location = location;
        newEntry.description = description;
        newEntry.ipfsCID = ipfsCID;
        newEntry.metadataHash = metadataHash;
        newEntry.isValid = true;
        newEntry.recorder = msg.sender;

        // Add additional data
        for (uint256 i = 0; i < additionalData.length; i += 2) {
            if (i + 1 < additionalData.length) {
                string memory key = additionalData[i];
                string memory value = additionalData[i + 1];
                newEntry.additionalData[key] = value;
                newEntry.dataKeys.push(key);
            }
        }

        // Update passport to entries mapping
        passportToEntries[passportId].push(entryId);

        // Update transfer history
        TransferHistory storage history = transferHistories[passportId];
        if (history.passportId == 0) {
            history.passportId = passportId;
            history.totalTransfers = 0;
            history.totalServices = 0;
        }

        history.transferEntryIds.push(entryId);
        history.totalTransfers++;
        history.currentOwner = to;
        history.lastTransferDate = block.timestamp;

        emit ProvenanceEntryCreated(entryId, passportId, entryType, from, to, location, ipfsCID);

        // Emit transfer event if it's a transfer
        if (entryType == ProvenanceType.TRANSFER) {
            emit TransferCompleted(passportId, from, to, entryId);
        }
    }

    /**
     * @dev Update provenance entry metadata
     * @param entryId Provenance entry ID
     * @param newIpfsCID New IPFS CID
     * @param newMetadataHash New metadata hash
     */
    function updateProvenanceEntry(
        uint256 entryId,
        string memory newIpfsCID,
        string memory newMetadataHash
    ) external validEntry(entryId) {
        ProvenanceEntry storage entry = provenanceEntries[entryId];
        require(entry.recorder == msg.sender, "Not authorized to update this entry");
        require(bytes(newIpfsCID).length > 0, "IPFS CID cannot be empty");
        require(bytes(newMetadataHash).length > 0, "Metadata hash cannot be empty");

        entry.ipfsCID = newIpfsCID;
        entry.metadataHash = newMetadataHash;

        emit ProvenanceEntryUpdated(entryId, newIpfsCID, msg.sender);
    }

    /**
     * @dev Add or update additional data for a provenance entry
     * @param entryId Provenance entry ID
     * @param key Data key
     * @param value Data value
     */
    function setProvenanceData(
        uint256 entryId,
        string memory key,
        string memory value
    ) external validEntry(entryId) {
        ProvenanceEntry storage entry = provenanceEntries[entryId];
        require(entry.recorder == msg.sender, "Not authorized to update this entry");
        require(bytes(key).length > 0, "Data key cannot be empty");

        bool isNewData = bytes(entry.additionalData[key]).length == 0;

        entry.additionalData[key] = value;

        if (isNewData) {
            entry.dataKeys.push(key);
            emit AdditionalDataAdded(entryId, key, value);
        }
    }

    /**
     * @dev Invalidate a provenance entry
     * @param entryId Provenance entry ID
     * @param reason Reason for invalidation
     */
    function invalidateProvenanceEntry(
        uint256 entryId,
        string memory reason
    ) external {
        require(provenanceEntries[entryId].entryId != 0, "Provenance entry does not exist");
        require(
            provenanceEntries[entryId].recorder == msg.sender || msg.sender == owner(),
            "Not authorized to invalidate this entry"
        );

        provenanceEntries[entryId].isValid = false;

        emit ProvenanceEntryInvalidated(entryId, reason, msg.sender);
    }

    // ============ SERVICE RECORD MANAGEMENT ============

    /**
     * @dev Create a new service record
     * @param passportId Product passport ID
     * @param serviceType Type of service
     * @param serviceProvider Service provider name
     * @param serviceDescription Service description
     * @param serviceDate Service date (Unix timestamp)
     * @param nextServiceDate Next service date (Unix timestamp)
     * @param ipfsCID IPFS CID containing service metadata
     * @param certificateNumber Certificate number
     * @param serviceDetails Array of key-value pairs for service details
     */
    function createServiceRecord(
        uint256 passportId,
        string memory serviceType,
        string memory serviceProvider,
        string memory serviceDescription,
        uint256 serviceDate,
        uint256 nextServiceDate,
        string memory ipfsCID,
        string memory certificateNumber,
        string[] memory serviceDetails
    ) external onlyAuthorizedServiceProvider notEmergencyStopped nonReentrant {
        require(passportId > 0, "Invalid passport ID");
        require(bytes(serviceType).length > 0, "Service type cannot be empty");
        require(bytes(serviceProvider).length > 0, "Service provider cannot be empty");
        require(bytes(serviceDescription).length > 0, "Service description cannot be empty");
        require(serviceDate <= block.timestamp, "Service date cannot be in the future");
        require(nextServiceDate > serviceDate, "Next service date must be after service date");
        require(bytes(ipfsCID).length > 0, "IPFS CID cannot be empty");

        _serviceIds = _serviceIds + 1;
        uint256 serviceId = _serviceIds;

        ServiceRecord storage newService = serviceRecords[serviceId];
        newService.serviceId = serviceId;
        newService.passportId = passportId;
        newService.serviceType = serviceType;
        newService.serviceProvider = serviceProvider;
        newService.serviceDescription = serviceDescription;
        newService.serviceDate = serviceDate;
        newService.nextServiceDate = nextServiceDate;
        newService.ipfsCID = ipfsCID;
        newService.certificateNumber = certificateNumber;
        newService.isValid = true;
        newService.serviceProviderAddress = msg.sender;

        // Add service details
        for (uint256 i = 0; i < serviceDetails.length; i += 2) {
            if (i + 1 < serviceDetails.length) {
                string memory key = serviceDetails[i];
                string memory value = serviceDetails[i + 1];
                newService.serviceDetails[key] = value;
                newService.detailKeys.push(key);
            }
        }

        // Update passport to services mapping
        passportToServices[passportId].push(serviceId);

        // Update transfer history
        TransferHistory storage history = transferHistories[passportId];
        if (history.passportId == 0) {
            history.passportId = passportId;
            history.totalTransfers = 0;
            history.totalServices = 0;
        }

        history.serviceEntryIds.push(serviceId);
        history.totalServices++;

        emit ServiceRecordCreated(serviceId, passportId, serviceType, serviceProvider, ipfsCID);
    }

    /**
     * @dev Update service record metadata
     * @param serviceId Service record ID
     * @param newIpfsCID New IPFS CID
     */
    function updateServiceRecord(
        uint256 serviceId,
        string memory newIpfsCID
    ) external validService(serviceId) {
        ServiceRecord storage service = serviceRecords[serviceId];
        require(service.serviceProviderAddress == msg.sender, "Not authorized to update this service");
        require(bytes(newIpfsCID).length > 0, "IPFS CID cannot be empty");

        service.ipfsCID = newIpfsCID;

        emit ServiceRecordUpdated(serviceId, newIpfsCID, msg.sender);
    }

    /**
     * @dev Invalidate a service record
     * @param serviceId Service record ID
     * @param reason Reason for invalidation
     */
    function invalidateServiceRecord(
        uint256 serviceId,
        string memory reason
    ) external {
        require(serviceRecords[serviceId].serviceId != 0, "Service record does not exist");
        require(
            serviceRecords[serviceId].serviceProviderAddress == msg.sender || msg.sender == owner(),
            "Not authorized to invalidate this service"
        );

        serviceRecords[serviceId].isValid = false;

        emit ServiceRecordInvalidated(serviceId, reason, msg.sender);
    }

    // ============ BATCH OPERATIONS ============

    /**
     * @dev Create multiple provenance entries in a single transaction
     */
    function createBatchProvenanceEntries(
        uint256[] memory passportIds,
        ProvenanceType[] memory entryTypes,
        address[] memory froms,
        address[] memory tos,
        string[] memory locations,
        string[] memory descriptions,
        string[] memory ipfsCIDs,
        string[] memory metadataHashes
    ) external onlyAuthorizedRecorder notEmergencyStopped nonReentrant {
        require(
            passportIds.length == entryTypes.length &&
            entryTypes.length == froms.length &&
            froms.length == tos.length &&
            tos.length == locations.length &&
            locations.length == descriptions.length &&
            descriptions.length == ipfsCIDs.length &&
            ipfsCIDs.length == metadataHashes.length,
            "Array lengths must match"
        );

        for (uint256 i = 0; i < passportIds.length; i++) {
            _createSingleProvenanceEntry(
                passportIds[i],
                entryTypes[i],
                froms[i],
                tos[i],
                locations[i],
                descriptions[i],
                ipfsCIDs[i],
                metadataHashes[i],
                new string[](0)
            );
        }
    }

    /**
     * @dev Internal function to create a single provenance entry
     */
    function _createSingleProvenanceEntry(
        uint256 passportId,
        ProvenanceType entryType,
        address from,
        address to,
        string memory location,
        string memory description,
        string memory ipfsCID,
        string memory metadataHash,
        string[] memory additionalData
    ) internal {
        require(passportId > 0, "Invalid passport ID");
        require(bytes(location).length > 0, "Location cannot be empty");
        require(bytes(description).length > 0, "Description cannot be empty");
        require(bytes(ipfsCID).length > 0, "IPFS CID cannot be empty");
        require(bytes(metadataHash).length > 0, "Metadata hash cannot be empty");

        _entryIds = _entryIds + 1;
        uint256 entryId = _entryIds;

        ProvenanceEntry storage newEntry = provenanceEntries[entryId];
        newEntry.entryId = entryId;
        newEntry.passportId = passportId;
        newEntry.entryType = entryType;
        newEntry.from = from;
        newEntry.to = to;
        newEntry.timestamp = block.timestamp;
        newEntry.location = location;
        newEntry.description = description;
        newEntry.ipfsCID = ipfsCID;
        newEntry.metadataHash = metadataHash;
        newEntry.isValid = true;
        newEntry.recorder = msg.sender;

        // Add additional data
        for (uint256 i = 0; i < additionalData.length; i += 2) {
            if (i + 1 < additionalData.length) {
                string memory key = additionalData[i];
                string memory value = additionalData[i + 1];
                newEntry.additionalData[key] = value;
                newEntry.dataKeys.push(key);
            }
        }

        // Update passport to entries mapping
        passportToEntries[passportId].push(entryId);

        // Update transfer history
        TransferHistory storage history = transferHistories[passportId];
        if (history.passportId == 0) {
            history.passportId = passportId;
            history.totalTransfers = 0;
            history.totalServices = 0;
        }

        history.transferEntryIds.push(entryId);
        history.totalTransfers++;
        history.currentOwner = to;
        history.lastTransferDate = block.timestamp;

        emit ProvenanceEntryCreated(entryId, passportId, entryType, from, to, location, ipfsCID);

        // Emit transfer event if it's a transfer
        if (entryType == ProvenanceType.TRANSFER) {
            emit TransferCompleted(passportId, from, to, entryId);
        }
    }

    // ============ ADMIN FUNCTIONS ============

    /**
     * @dev Authorize a recorder
     * @param recorder Address to authorize
     */
    function authorizeRecorder(address recorder) external onlyOwner {
        require(recorder != address(0), "Invalid address");
        authorizedRecorders[recorder] = true;
    }

    /**
     * @dev Authorize a service provider
     * @param serviceProvider Address to authorize
     */
    function authorizeServiceProvider(address serviceProvider) external onlyOwner {
        require(serviceProvider != address(0), "Invalid address");
        authorizedServiceProviders[serviceProvider] = true;
    }

    /**
     * @dev Authorize an operator
     * @param operator Address to authorize
     */
    function authorizeOperator(address operator) external onlyOwner {
        require(operator != address(0), "Invalid address");
        authorizedOperators[operator] = true;
    }

    /**
     * @dev Revoke authorizations
     * @param target Address to revoke
     */
    function revokeAuthorization(address target) external onlyOwner {
        authorizedRecorders[target] = false;
        authorizedServiceProviders[target] = false;
        authorizedOperators[target] = false;
    }

    /**
     * @dev Set fees
     * @param newProvenanceFee New provenance entry fee
     * @param newServiceFee New service record fee
     */
    function setFees(uint256 newProvenanceFee, uint256 newServiceFee) external onlyOwner {
        provenanceEntryFee = newProvenanceFee;
        serviceRecordFee = newServiceFee;
    }

    /**
     * @dev Activate emergency stop
     */
    function activateEmergencyStop() external onlyOwner {
        emergencyStop = true;
    }

    /**
     * @dev Deactivate emergency stop
     */
    function deactivateEmergencyStop() external onlyOwner {
        emergencyStop = false;
    }

    /**
     * @dev Pause contract
     */
    function pause() external onlyOwner {
        _pause();
    }

    /**
     * @dev Unpause contract
     */
    function unpause() external onlyOwner {
        _unpause();
    }

    /**
     * @dev Withdraw fees
     */
    function withdrawFees() external onlyOwner {
        uint256 balance = address(this).balance;
        require(balance > 0, "No fees to withdraw");

        (bool success, ) = payable(owner()).call{value: balance}("");
        require(success, "Transfer failed");
    }

    // ============ VIEW FUNCTIONS ============

    /**
     * @dev Get provenance entry details
     * @param entryId Provenance entry ID
     */
    function getProvenanceEntryDetails(uint256 entryId) external view returns (
        uint256 passportId,
        ProvenanceType entryType,
        address from,
        address to,
        uint256 timestamp,
        string memory location,
        string memory description,
        string memory ipfsCID,
        string memory metadataHash,
        bool isValid,
        address recorder
    ) {
        ProvenanceEntry storage entry = provenanceEntries[entryId];
        return (
            entry.passportId,
            entry.entryType,
            entry.from,
            entry.to,
            entry.timestamp,
            entry.location,
            entry.description,
            entry.ipfsCID,
            entry.metadataHash,
            entry.isValid,
            entry.recorder
        );
    }

    /**
     * @dev Get service record details
     * @param serviceId Service record ID
     */
    function getServiceRecordDetails(uint256 serviceId) external view returns (
        uint256 passportId,
        string memory serviceType,
        string memory serviceProvider,
        string memory serviceDescription,
        uint256 serviceDate,
        uint256 nextServiceDate,
        string memory ipfsCID,
        string memory certificateNumber,
        bool isValid,
        address serviceProviderAddress
    ) {
        ServiceRecord storage service = serviceRecords[serviceId];
        return (
            service.passportId,
            service.serviceType,
            service.serviceProvider,
            service.serviceDescription,
            service.serviceDate,
            service.nextServiceDate,
            service.ipfsCID,
            service.certificateNumber,
            service.isValid,
            service.serviceProviderAddress
        );
    }

    /**
     * @dev Get transfer history for a passport
     * @param passportId Product passport ID
     */
    function getTransferHistory(uint256 passportId) external view returns (
        uint256 totalTransfers,
        uint256 totalServices,
        address currentOwner,
        uint256 lastTransferDate,
        uint256[] memory transferEntryIds,
        uint256[] memory serviceEntryIds
    ) {
        TransferHistory storage history = transferHistories[passportId];
        return (
            history.totalTransfers,
            history.totalServices,
            history.currentOwner,
            history.lastTransferDate,
            history.transferEntryIds,
            history.serviceEntryIds
        );
    }

    /**
     * @dev Get all provenance entries for a passport
     * @param passportId Product passport ID
     */
    function getPassportEntries(uint256 passportId) external view returns (uint256[] memory) {
        return passportToEntries[passportId];
    }

    /**
     * @dev Get all service records for a passport
     * @param passportId Product passport ID
     */
    function getPassportServices(uint256 passportId) external view returns (uint256[] memory) {
        return passportToServices[passportId];
    }

    /**
     * @dev Get additional data for a provenance entry
     * @param entryId Provenance entry ID
     * @param key Data key
     */
    function getProvenanceData(uint256 entryId, string memory key) external view returns (string memory) {
        return provenanceEntries[entryId].additionalData[key];
    }

    /**
     * @dev Get all data keys for a provenance entry
     * @param entryId Provenance entry ID
     */
    function getProvenanceDataKeys(uint256 entryId) external view returns (string[] memory) {
        return provenanceEntries[entryId].dataKeys;
    }

    /**
     * @dev Get service details for a service record
     * @param serviceId Service record ID
     * @param key Detail key
     */
    function getServiceDetail(uint256 serviceId, string memory key) external view returns (string memory) {
        return serviceRecords[serviceId].serviceDetails[key];
    }

    /**
     * @dev Get all detail keys for a service record
     * @param serviceId Service record ID
     */
    function getServiceDetailKeys(uint256 serviceId) external view returns (string[] memory) {
        return serviceRecords[serviceId].detailKeys;
    }

    /**
     * @dev Get total number of provenance entries
     */
    function getTotalProvenanceEntries() external view returns (uint256) {
        return _entryIds - 1;
    }

    /**
     * @dev Get total number of service records
     */
    function getTotalServiceRecords() external view returns (uint256) {
        return _serviceIds - 1;
    }

    /**
     * @dev Get provenance entries by type for a passport
     * @param passportId Product passport ID
     * @param entryType Type of entry to filter
     */
    function getEntriesByType(uint256 passportId, ProvenanceType entryType) external view returns (uint256[] memory) {
        uint256[] memory allEntries = passportToEntries[passportId];
        uint256[] memory filteredEntries = new uint256[](allEntries.length);
        uint256 count = 0;

        for (uint256 i = 0; i < allEntries.length; i++) {
            if (provenanceEntries[allEntries[i]].entryType == entryType && 
                provenanceEntries[allEntries[i]].isValid) {
                filteredEntries[count] = allEntries[i];
                count++;
            }
        }

        // Resize array to actual count
        uint256[] memory result = new uint256[](count);
        for (uint256 i = 0; i < count; i++) {
            result[i] = filteredEntries[i];
        }

        return result;
    }

    // ============ RECEIVE FUNCTION ============

    receive() external payable {
        // Contract can receive ETH for fees
    }
}

contracts/TrataTechProvenanceUpgradeable.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/PausableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/ReentrancyGuardUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/metatx/ERC2771ContextUpgradeable.sol";

import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import "@openzeppelin/contracts/utils/Strings.sol";

/**
 * @title TrataTechProvenanceUpgradeable
 * @dev Upgradeable and gasless version of Provenance Contract for maintaining immutable logs of transfers and service history
 * @author Advanced Developer
 */
contract TrataTechProvenanceUpgradeable is 
    Initializable,
    OwnableUpgradeable,
    PausableUpgradeable,
    ReentrancyGuardUpgradeable,
    UUPSUpgradeable,
    ERC2771ContextUpgradeable
{
    using ECDSA for bytes32;
    using Strings for uint256;

    // ============ STRUCTS ============

    struct ProvenanceEntry {
        uint256 entryId;
        uint256 passportId;
        ProvenanceType entryType;
        address from;
        address to;
        uint256 timestamp;
        string location;
        string description;
        string ipfsCID;
        string metadataHash;
        bool isValid;
        address recorder;
        mapping(string => string) additionalData;
        string[] dataKeys;
    }

    struct ServiceRecord {
        uint256 serviceId;
        uint256 passportId;
        string serviceType;
        string serviceProvider;
        string serviceDescription;
        uint256 serviceDate;
        uint256 nextServiceDate;
        string ipfsCID;
        string certificateNumber;
        bool isValid;
        address serviceProviderAddress;
        mapping(string => string) serviceDetails;
        string[] detailKeys;
    }

    struct TransferHistory {
        uint256 passportId;
        uint256[] transferEntryIds;
        uint256[] serviceEntryIds;
        uint256 totalTransfers;
        uint256 totalServices;
        address currentOwner;
        uint256 lastTransferDate;
    }

    enum ProvenanceType {
        MANUFACTURING,
        TRANSFER,
        SERVICE,
        REPAIR,
        MAINTENANCE,
        INSPECTION,
        CERTIFICATION,
        RECALL,
        DISPOSAL,
        CUSTOM
    }

    // ============ STATE VARIABLES ============

    uint256 private _entryIds;
    uint256 private _serviceIds;

    // Mappings
    mapping(uint256 => ProvenanceEntry) public provenanceEntries;
    mapping(uint256 => ServiceRecord) public serviceRecords;
    mapping(uint256 => TransferHistory) public transferHistories;
    mapping(uint256 => uint256[]) public passportToEntries;
    mapping(uint256 => uint256[]) public passportToServices;
    mapping(address => bool) public authorizedRecorders;
    mapping(address => bool) public authorizedServiceProviders;
    mapping(address => bool) public authorizedOperators;

    // Fee structure
    uint256 public provenanceEntryFee;
    uint256 public serviceRecordFee;

    // Emergency controls
    bool public emergencyStop;

    // Batch operation limits
    uint256 public constant MAX_BATCH_SIZE = 25;

    // Storage gap for future upgrades
    uint256[49] private __gap;

    // ============ EVENTS ============

    event ProvenanceEntryCreated(
        uint256 indexed entryId,
        uint256 indexed passportId,
        ProvenanceType entryType,
        address indexed from,
        address to,
        string location,
        string ipfsCID
    );

    event ProvenanceEntryUpdated(
        uint256 indexed entryId,
        string ipfsCID,
        address indexed updater
    );

    event ProvenanceEntryInvalidated(
        uint256 indexed entryId,
        string reason,
        address indexed invalidator
    );

    event ServiceRecordCreated(
        uint256 indexed serviceId,
        uint256 indexed passportId,
        string serviceType,
        string serviceProvider,
        string ipfsCID
    );

    event ServiceRecordUpdated(
        uint256 indexed serviceId,
        string ipfsCID,
        address indexed updater
    );

    event ServiceRecordInvalidated(
        uint256 indexed serviceId,
        string reason,
        address indexed invalidator
    );

    event TransferCompleted(
        uint256 indexed passportId,
        address indexed from,
        address indexed to,
        uint256 entryId
    );

    event AdditionalDataAdded(
        uint256 indexed entryId,
        string key,
        string value
    );

    // ============ MODIFIERS ============

    modifier onlyAuthorizedRecorder() {
        require(authorizedRecorders[_msgSender()] || _msgSender() == owner(), "Not authorized recorder");
        _;
    }

    modifier onlyAuthorizedServiceProvider() {
        require(authorizedServiceProviders[_msgSender()] || _msgSender() == owner(), "Not authorized service provider");
        _;
    }

    modifier onlyAuthorizedOperator() {
        require(authorizedOperators[_msgSender()] || _msgSender() == owner(), "Not authorized operator");
        _;
    }

    modifier notEmergencyStopped() {
        require(!emergencyStop, "Contract is emergency stopped");
        _;
    }

    modifier validEntry(uint256 entryId) {
        require(provenanceEntries[entryId].entryId != 0, "Provenance entry does not exist");
        require(provenanceEntries[entryId].isValid, "Provenance entry is invalid");
        _;
    }

    modifier validService(uint256 serviceId) {
        require(serviceRecords[serviceId].serviceId != 0, "Service record does not exist");
        require(serviceRecords[serviceId].isValid, "Service record is invalid");
        _;
    }

    // ============ INITIALIZATION ============

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor(address trustedForwarder) ERC2771ContextUpgradeable(trustedForwarder) {
        require(trustedForwarder != address(0), "TrataTech: Invalid trusted forwarder");
        _disableInitializers();
    }

    function initialize(address initialOwner, address trustedForwarder) public initializer {
        __Ownable_init(initialOwner);
        __Pausable_init();
        __ReentrancyGuard_init();
        __UUPSUpgradeable_init();
        // ERC2771Context initialization removed - constructor handles this

        _entryIds = 1; // Start from 1
        _serviceIds = 1; // Start from 1
        provenanceEntryFee = 0.001 ether;
        serviceRecordFee = 0.002 ether;
    }

    // ============ UUPS UPGRADE AUTHORIZATION ============

    function _authorizeUpgrade(address newImplementation) internal override onlyOwner {}

    // ============ ERC2771 OVERRIDES FOR GASLESS ============

    function _msgSender() internal view virtual override(ContextUpgradeable, ERC2771ContextUpgradeable) returns (address) {
        return ERC2771ContextUpgradeable._msgSender();
    }

    function _msgData() internal view virtual override(ContextUpgradeable, ERC2771ContextUpgradeable) returns (bytes calldata) {
        return ERC2771ContextUpgradeable._msgData();
    }

    function _contextSuffixLength() internal view virtual override(ContextUpgradeable, ERC2771ContextUpgradeable) returns (uint256) {
        return ERC2771ContextUpgradeable._contextSuffixLength();
    }

    // ============ PROVENANCE ENTRY MANAGEMENT ============

    function createProvenanceEntry(
        uint256 passportId,
        ProvenanceType entryType,
        address from,
        address to,
        string memory location,
        string memory description,
        string memory ipfsCID,
        string memory metadataHash,
        string[] memory additionalData
    ) external onlyAuthorizedRecorder notEmergencyStopped nonReentrant {
        require(passportId > 0, "Invalid passport ID");
        require(bytes(location).length > 0, "Location cannot be empty");
        require(bytes(description).length > 0, "Description cannot be empty");
        require(bytes(ipfsCID).length > 0, "IPFS CID cannot be empty");
        require(bytes(metadataHash).length > 0, "Metadata hash cannot be empty");

        _entryIds = _entryIds + 1;
        uint256 entryId = _entryIds;

        ProvenanceEntry storage newEntry = provenanceEntries[entryId];
        newEntry.entryId = entryId;
        newEntry.passportId = passportId;
        newEntry.entryType = entryType;
        newEntry.from = from;
        newEntry.to = to;
        newEntry.timestamp = block.timestamp;
        newEntry.location = location;
        newEntry.description = description;
        newEntry.ipfsCID = ipfsCID;
        newEntry.metadataHash = metadataHash;
        newEntry.isValid = true;
        newEntry.recorder = _msgSender();

        // Add additional data
        for (uint256 i = 0; i < additionalData.length; i += 2) {
            if (i + 1 < additionalData.length) {
                string memory key = additionalData[i];
                string memory value = additionalData[i + 1];
                newEntry.additionalData[key] = value;
                newEntry.dataKeys.push(key);
            }
        }

        // Update passport to entries mapping
        passportToEntries[passportId].push(entryId);

        // Update transfer history
        TransferHistory storage history = transferHistories[passportId];
        if (history.passportId == 0) {
            history.passportId = passportId;
            history.totalTransfers = 0;
            history.totalServices = 0;
        }

        history.transferEntryIds.push(entryId);
        history.totalTransfers++;
        history.currentOwner = to;
        history.lastTransferDate = block.timestamp;

        emit ProvenanceEntryCreated(entryId, passportId, entryType, from, to, location, ipfsCID);

        // Emit transfer event if it's a transfer
        if (entryType == ProvenanceType.TRANSFER) {
            emit TransferCompleted(passportId, from, to, entryId);
        }
    }

    function updateProvenanceEntry(
        uint256 entryId,
        string memory newIpfsCID,
        string memory newMetadataHash
    ) external validEntry(entryId) {
        ProvenanceEntry storage entry = provenanceEntries[entryId];
        require(entry.recorder == _msgSender(), "Not authorized to update this entry");
        require(bytes(newIpfsCID).length > 0, "IPFS CID cannot be empty");
        require(bytes(newMetadataHash).length > 0, "Metadata hash cannot be empty");

        entry.ipfsCID = newIpfsCID;
        entry.metadataHash = newMetadataHash;

        emit ProvenanceEntryUpdated(entryId, newIpfsCID, _msgSender());
    }

    function setProvenanceData(
        uint256 entryId,
        string memory key,
        string memory value
    ) external validEntry(entryId) {
        ProvenanceEntry storage entry = provenanceEntries[entryId];
        require(entry.recorder == _msgSender(), "Not authorized to update this entry");
        require(bytes(key).length > 0, "Data key cannot be empty");

        bool isNewData = bytes(entry.additionalData[key]).length == 0;

        entry.additionalData[key] = value;

        if (isNewData) {
            entry.dataKeys.push(key);
            emit AdditionalDataAdded(entryId, key, value);
        }
    }

    function invalidateProvenanceEntry(
        uint256 entryId,
        string memory reason
    ) external {
        require(provenanceEntries[entryId].entryId != 0, "Provenance entry does not exist");
        require(
            provenanceEntries[entryId].recorder == _msgSender() || _msgSender() == owner(),
            "Not authorized to invalidate this entry"
        );

        provenanceEntries[entryId].isValid = false;

        emit ProvenanceEntryInvalidated(entryId, reason, _msgSender());
    }

    // ============ SERVICE RECORD MANAGEMENT ============

    function createServiceRecord(
        uint256 passportId,
        string memory serviceType,
        string memory serviceProvider,
        string memory serviceDescription,
        uint256 serviceDate,
        uint256 nextServiceDate,
        string memory ipfsCID,
        string memory certificateNumber,
        string[] memory serviceDetails
    ) external onlyAuthorizedServiceProvider notEmergencyStopped nonReentrant {
        require(passportId > 0, "Invalid passport ID");
        require(bytes(serviceType).length > 0, "Service type cannot be empty");
        require(bytes(serviceProvider).length > 0, "Service provider cannot be empty");
        require(bytes(serviceDescription).length > 0, "Service description cannot be empty");
        require(serviceDate <= block.timestamp, "Service date cannot be in the future");
        require(nextServiceDate > serviceDate, "Next service date must be after service date");
        require(bytes(ipfsCID).length > 0, "IPFS CID cannot be empty");

        _serviceIds = _serviceIds + 1;
        uint256 serviceId = _serviceIds;

        ServiceRecord storage newService = serviceRecords[serviceId];
        newService.serviceId = serviceId;
        newService.passportId = passportId;
        newService.serviceType = serviceType;
        newService.serviceProvider = serviceProvider;
        newService.serviceDescription = serviceDescription;
        newService.serviceDate = serviceDate;
        newService.nextServiceDate = nextServiceDate;
        newService.ipfsCID = ipfsCID;
        newService.certificateNumber = certificateNumber;
        newService.isValid = true;
        newService.serviceProviderAddress = _msgSender();

        // Add service details
        for (uint256 i = 0; i < serviceDetails.length; i += 2) {
            if (i + 1 < serviceDetails.length) {
                string memory key = serviceDetails[i];
                string memory value = serviceDetails[i + 1];
                newService.serviceDetails[key] = value;
                newService.detailKeys.push(key);
            }
        }

        // Update passport to services mapping
        passportToServices[passportId].push(serviceId);

        // Update transfer history
        TransferHistory storage history = transferHistories[passportId];
        if (history.passportId == 0) {
            history.passportId = passportId;
            history.totalTransfers = 0;
            history.totalServices = 0;
        }

        history.serviceEntryIds.push(serviceId);
        history.totalServices++;

        emit ServiceRecordCreated(serviceId, passportId, serviceType, serviceProvider, ipfsCID);
    }

    function updateServiceRecord(
        uint256 serviceId,
        string memory newIpfsCID
    ) external validService(serviceId) {
        ServiceRecord storage service = serviceRecords[serviceId];
        require(service.serviceProviderAddress == _msgSender(), "Not authorized to update this service");
        require(bytes(newIpfsCID).length > 0, "IPFS CID cannot be empty");

        service.ipfsCID = newIpfsCID;

        emit ServiceRecordUpdated(serviceId, newIpfsCID, _msgSender());
    }

    function invalidateServiceRecord(
        uint256 serviceId,
        string memory reason
    ) external {
        require(serviceRecords[serviceId].serviceId != 0, "Service record does not exist");
        require(
            serviceRecords[serviceId].serviceProviderAddress == _msgSender() || _msgSender() == owner(),
            "Not authorized to invalidate this service"
        );

        serviceRecords[serviceId].isValid = false;

        emit ServiceRecordInvalidated(serviceId, reason, _msgSender());
    }

    // ============ BATCH OPERATIONS ============

    function createBatchProvenanceEntries(
        uint256[] memory passportIds,
        ProvenanceType[] memory entryTypes,
        address[] memory froms,
        address[] memory tos,
        string[] memory locations,
        string[] memory descriptions,
        string[] memory ipfsCIDs,
        string[] memory metadataHashes
    ) external onlyAuthorizedRecorder notEmergencyStopped nonReentrant {
        require(passportIds.length <= MAX_BATCH_SIZE, "Batch size too large");
        require(passportIds.length > 0, "Empty batch not allowed");
        require(
            passportIds.length == entryTypes.length &&
            entryTypes.length == froms.length &&
            froms.length == tos.length &&
            tos.length == locations.length &&
            locations.length == descriptions.length &&
            descriptions.length == ipfsCIDs.length &&
            ipfsCIDs.length == metadataHashes.length,
            "Array lengths must match"
        );

        for (uint256 i = 0; i < passportIds.length; i++) {
            _createSingleProvenanceEntry(
                passportIds[i],
                entryTypes[i],
                froms[i],
                tos[i],
                locations[i],
                descriptions[i],
                ipfsCIDs[i],
                metadataHashes[i],
                new string[](0)
            );
        }
    }

    function _createSingleProvenanceEntry(
        uint256 passportId,
        ProvenanceType entryType,
        address from,
        address to,
        string memory location,
        string memory description,
        string memory ipfsCID,
        string memory metadataHash,
        string[] memory additionalData
    ) internal {
        require(passportId > 0, "Invalid passport ID");
        require(bytes(location).length > 0, "Location cannot be empty");
        require(bytes(description).length > 0, "Description cannot be empty");
        require(bytes(ipfsCID).length > 0, "IPFS CID cannot be empty");
        require(bytes(metadataHash).length > 0, "Metadata hash cannot be empty");

        _entryIds = _entryIds + 1;
        uint256 entryId = _entryIds;

        ProvenanceEntry storage newEntry = provenanceEntries[entryId];
        newEntry.entryId = entryId;
        newEntry.passportId = passportId;
        newEntry.entryType = entryType;
        newEntry.from = from;
        newEntry.to = to;
        newEntry.timestamp = block.timestamp;
        newEntry.location = location;
        newEntry.description = description;
        newEntry.ipfsCID = ipfsCID;
        newEntry.metadataHash = metadataHash;
        newEntry.isValid = true;
        newEntry.recorder = _msgSender();

        // Add additional data
        for (uint256 i = 0; i < additionalData.length; i += 2) {
            if (i + 1 < additionalData.length) {
                string memory key = additionalData[i];
                string memory value = additionalData[i + 1];
                newEntry.additionalData[key] = value;
                newEntry.dataKeys.push(key);
            }
        }

        // Update passport to entries mapping
        passportToEntries[passportId].push(entryId);

        // Update transfer history
        TransferHistory storage history = transferHistories[passportId];
        if (history.passportId == 0) {
            history.passportId = passportId;
            history.totalTransfers = 0;
            history.totalServices = 0;
        }

        history.transferEntryIds.push(entryId);
        history.totalTransfers++;
        history.currentOwner = to;
        history.lastTransferDate = block.timestamp;

        emit ProvenanceEntryCreated(entryId, passportId, entryType, from, to, location, ipfsCID);

        // Emit transfer event if it's a transfer
        if (entryType == ProvenanceType.TRANSFER) {
            emit TransferCompleted(passportId, from, to, entryId);
        }
    }

    // ============ ADMIN FUNCTIONS ============

    function authorizeRecorder(address recorder) external onlyOwner {
        require(recorder != address(0), "Invalid address");
        authorizedRecorders[recorder] = true;
    }

    function authorizeServiceProvider(address serviceProvider) external onlyOwner {
        require(serviceProvider != address(0), "Invalid address");
        authorizedServiceProviders[serviceProvider] = true;
    }

    function authorizeOperator(address operator) external onlyOwner {
        require(operator != address(0), "Invalid address");
        authorizedOperators[operator] = true;
    }

    function revokeAuthorization(address target) external onlyOwner {
        authorizedRecorders[target] = false;
        authorizedServiceProviders[target] = false;
        authorizedOperators[target] = false;
    }

    function setFees(uint256 newProvenanceFee, uint256 newServiceFee) external onlyOwner {
        provenanceEntryFee = newProvenanceFee;
        serviceRecordFee = newServiceFee;
    }

    function activateEmergencyStop() external onlyOwner {
        emergencyStop = true;
    }

    function deactivateEmergencyStop() external onlyOwner {
        emergencyStop = false;
    }

    function pause() external onlyOwner {
        _pause();
    }

    function unpause() external onlyOwner {
        _unpause();
    }

    // Fee withdrawal removed - no blockchain payments

    // ============ VIEW FUNCTIONS ============

    function getProvenanceEntryDetails(uint256 entryId) external view returns (
        uint256 passportId,
        ProvenanceType entryType,
        address from,
        address to,
        uint256 timestamp,
        string memory location,
        string memory description,
        string memory ipfsCID,
        string memory metadataHash,
        bool isValid,
        address recorder
    ) {
        ProvenanceEntry storage entry = provenanceEntries[entryId];
        return (
            entry.passportId,
            entry.entryType,
            entry.from,
            entry.to,
            entry.timestamp,
            entry.location,
            entry.description,
            entry.ipfsCID,
            entry.metadataHash,
            entry.isValid,
            entry.recorder
        );
    }

    function getServiceRecordDetails(uint256 serviceId) external view returns (
        uint256 passportId,
        string memory serviceType,
        string memory serviceProvider,
        string memory serviceDescription,
        uint256 serviceDate,
        uint256 nextServiceDate,
        string memory ipfsCID,
        string memory certificateNumber,
        bool isValid,
        address serviceProviderAddress
    ) {
        ServiceRecord storage service = serviceRecords[serviceId];
        return (
            service.passportId,
            service.serviceType,
            service.serviceProvider,
            service.serviceDescription,
            service.serviceDate,
            service.nextServiceDate,
            service.ipfsCID,
            service.certificateNumber,
            service.isValid,
            service.serviceProviderAddress
        );
    }

    function getTransferHistory(uint256 passportId) external view returns (
        uint256 totalTransfers,
        uint256 totalServices,
        address currentOwner,
        uint256 lastTransferDate,
        uint256[] memory transferEntryIds,
        uint256[] memory serviceEntryIds
    ) {
        TransferHistory storage history = transferHistories[passportId];
        return (
            history.totalTransfers,
            history.totalServices,
            history.currentOwner,
            history.lastTransferDate,
            history.transferEntryIds,
            history.serviceEntryIds
        );
    }

    function getPassportEntries(uint256 passportId) external view returns (uint256[] memory) {
        return passportToEntries[passportId];
    }

    function getPassportServices(uint256 passportId) external view returns (uint256[] memory) {
        return passportToServices[passportId];
    }

    function getProvenanceData(uint256 entryId, string memory key) external view returns (string memory) {
        return provenanceEntries[entryId].additionalData[key];
    }

    function getProvenanceDataKeys(uint256 entryId) external view returns (string[] memory) {
        return provenanceEntries[entryId].dataKeys;
    }

    function getServiceDetail(uint256 serviceId, string memory key) external view returns (string memory) {
        return serviceRecords[serviceId].serviceDetails[key];
    }

    function getServiceDetailKeys(uint256 serviceId) external view returns (string[] memory) {
        return serviceRecords[serviceId].detailKeys;
    }

    function getTotalProvenanceEntries() external view returns (uint256) {
        return _entryIds - 1;
    }

    function getTotalServiceRecords() external view returns (uint256) {
        return _serviceIds - 1;
    }

    function getEntriesByType(uint256 passportId, ProvenanceType entryType) external view returns (uint256[] memory) {
        uint256[] memory allEntries = passportToEntries[passportId];
        uint256[] memory filteredEntries = new uint256[](allEntries.length);
        uint256 count = 0;

        for (uint256 i = 0; i < allEntries.length; i++) {
            if (provenanceEntries[allEntries[i]].entryType == entryType && 
                provenanceEntries[allEntries[i]].isValid) {
                filteredEntries[count] = allEntries[i];
                count++;
            }
        }

        // Resize array to actual count
        uint256[] memory result = new uint256[](count);
        for (uint256 i = 0; i < count; i++) {
            result[i] = filteredEntries[i];
        }

        return result;
    }

    // ============ VERSION FUNCTION ============

    function version() external pure returns (string memory) {
        return "1.0.0";
    }

    // ============ RECEIVE FUNCTION ============

    // Receive function removed - no blockchain payments
}

